type RecordDetailTab = "contact" | "deal" | "trello" | "communication" | "sales" | "history";

function getRecordTabLabel(tab: RecordDetailTab) {
  switch (tab) {
    case "deal":
      return "Verkauf & Herkunft";
    case "trello":
      return "Karten & Medien";
    case "communication":
      return "Kommunikation";
    case "sales":
      return "Vertrieb & Anrufe";
    case "history":
      return "Verlauf";
    default:
      return "Kontakt";
  }
}

function getRecordTabOpenLabel(tab: RecordDetailTab) {
  switch (tab) {
    case "deal":
      return "Verkauf & Herkunft öffnen";
    case "trello":
      return "Karten & Medien öffnen";
    case "communication":
      return "Kommunikation öffnen";
    case "sales":
      return "Vertrieb & Anrufe öffnen";
    case "history":
      return "Verlauf öffnen";
    default:
      return "Kontakt öffnen";
  }
}

function getCasePlanContextButtonLabel(step: Pick<CasePlanStep, "action" | "tab">) {
  if (step.action === "open_contact_dossier") return "Kontaktdossier öffnen";
  if (step.action === "open_commercial_desk") return "Abschlussspur öffnen";
  return getRecordTabOpenLabel(step.tab);
}

