type SessionContextOpenHandler = (
  record: CustomerSearchResult,
  label: string,
  requestIds: string[],
  badgeLabel: SessionBadgeLabel,
  preferredTab?: RecordDetailTab | null,
) => void;

function openRecordInSessionContext({
  record,
  label,
  requestIds,
  badgeLabel,
  preferredTab,
  onOpen,
  onOpenPortfolio,
  onOpenCommercialDesk,
}: {
  record: CustomerSearchResult;
  label: string;
  requestIds: string[];
  badgeLabel: SessionBadgeLabel;
  preferredTab?: RecordDetailTab | null;
  onOpen: SessionContextOpenHandler;
  onOpenPortfolio: (record: CustomerSearchResult) => void;
  onOpenCommercialDesk: (record: CustomerSearchResult) => void;
}) {
  if (badgeLabel === "Kontaktdossier") {
    onOpenPortfolio(record);
    return;
  }
  if (badgeLabel === "Abschluss" || badgeLabel === "Kaufinteresse") {
    onOpenCommercialDesk(record);
    return;
  }
  onOpen(record, label, requestIds, badgeLabel, preferredTab);
}

function openContactPortfolioRequestId(
  onOpenRequestId: ((requestId: string, options?: RequestIdSessionOpenOptions) => void) | undefined,
  record: CustomerSearchResult,
  targetRequestId: string,
  preferredTab: RecordDetailTab | null,
) {
  onOpenRequestId?.(targetRequestId, buildContactPortfolioSessionOptions(record, preferredTab));
}

function openContactPortfolioFocusRequestId(
  onOpenRequestId: ((requestId: string, options?: RequestIdSessionOpenOptions) => void) | undefined,
  record: CustomerSearchResult,
  fallbackTab?: RecordDetailTab,
) {
  onOpenRequestId?.(record.requestId, buildContactPortfolioFocusSessionOptions(record, fallbackTab));
}

function openCommercialDeskRequestId(
  onOpenRequestId: ((requestId: string, options?: RequestIdSessionOpenOptions) => void) | undefined,
  record: CustomerSearchResult,
  commercialDeskRecords?: CommercialDeskItem[],
) {
  onOpenRequestId?.(record.requestId, buildCommercialSessionOptions(record, commercialDeskRecords));
}

function buildStoredCaseSessionOpenOptions(entry: RecentCase, entries: RecentCase[], label: string): RequestIdSessionOpenOptions {
  return {
    label,
    badgeLabel: entry.badgeLabel,
    preferredTab: entry.preferredTab ?? null,
    requestIds: entries.map((item) => item.requestId),
    ...buildRequestIdSessionMaps(entries, {
      preferredTabByRecord: (item) => item.preferredTab ?? null,
      badgeLabelByRecord: (item) => item.badgeLabel,
    }),
    source: "workboard",
  };
}

function buildRecordSessionOpenOptions<T extends { requestId: string }>({
  records,
  label,
  source,
  badgeLabel,
  preferredTab,
  preferredTabByRecord,
  badgeLabelByRecord,
}: {
  records: T[];
  label: string;
  source: FocusSession["source"];
  badgeLabel?: SessionBadgeLabel;
  preferredTab?: RecordDetailTab | null;
  preferredTabByRecord?: (record: T) => RecordDetailTab | null;
  badgeLabelByRecord?: (record: T) => SessionBadgeLabel | undefined;
}): RequestIdSessionOpenOptions {
  return {
    label,
    source,
    badgeLabel,
    preferredTab: preferredTab ?? null,
    requestIds: records.map((record) => record.requestId),
    ...buildRequestIdSessionMaps(records, {
      preferredTabByRecord: (record) => (preferredTabByRecord ? preferredTabByRecord(record) : preferredTab ?? null),
      badgeLabelByRecord: (record) => (badgeLabelByRecord ? badgeLabelByRecord(record) : badgeLabel),
    }),
  };
}

function buildRecordSessionMaps(records: CustomerSearchResult[]) {
  return buildRequestIdSessionMaps(records, {
    preferredTabByRecord: (record) => resolveRecordSessionMeta(record).preferredTab ?? inferPreferredTab(record),
    badgeLabelByRecord: (record) => resolveRecordSessionMeta(record).badgeLabel,
  });
}

