const EMPTY_CASE_FLOW_PROGRESS: CaseFlowProgressState = {
  completedKeys: [],
  lastFlowKey: null,
  updatedAt: null,
};

const CaseFlowProgressContext = createContext<{
  getProgress: (requestId: string) => CaseFlowProgressState;
  setLastFlowKey: (requestId: string, flow: Pick<CaseFlow, "key" | "title"> | null, totalSteps?: number | null) => void;
  markCompleted: (
    requestId: string,
    step: Pick<CasePlanStep, "key" | "label">,
    flow?: Pick<CaseFlow, "key" | "title"> | null,
    totalSteps?: number | null,
  ) => void;
  resetProgress: (requestId: string, flow?: Pick<CaseFlow, "key" | "title"> | null, totalSteps?: number | null) => void;
}>({
  getProgress: () => EMPTY_CASE_FLOW_PROGRESS,
  setLastFlowKey: () => {},
  markCompleted: () => {},
  resetProgress: () => {},
});

function useCaseFlowProgress() {
  return useContext(CaseFlowProgressContext);
}

function resolveCaseFlowProgress(record: CustomerSearchResult, localProgress: CaseFlowProgressState) {
  if (localProgress.completedKeys.length || localProgress.lastFlowKey) {
    return localProgress;
  }

  return {
    completedKeys: record.caseFlow.completedKeys,
    lastFlowKey: (record.caseFlow.flowKey as CaseFlow["key"] | null) || null,
    updatedAt: record.caseFlow.updatedAt,
  };
}

function dedupeRecords(groups: CustomerSearchResult[][]) {
  const byId = new Map<string, CustomerSearchResult>();
  for (const group of groups) {
    for (const record of group) {
      if (!byId.has(record.requestId)) {
        byId.set(record.requestId, record);
      }
    }
  }
  return [...byId.values()];
}

function isViewedWithoutOrder(record: CustomerSearchResult) {
  return Boolean(record.quote?.viewedAt) && !record.order && record.orderDiagnostic.status === "unlinked";
}

function resolveRecordSessionMeta(record: CustomerSearchResult) {
  const repairGap = getPrimaryRepairGap(record);
  const repairGapKey =
    repairGap &&
    (
      [
        "email_drift",
        "blocked_followups",
        "trello_context_thin",
        "viewed_without_order",
        "order_open_ops",
        "callback_no_phone",
        "outbound_only_followup",
      ] as const
    ).includes(repairGap.id as SystemGapKey)
      ? (repairGap.id as SystemGapKey)
      : null;

  return getRecordSessionMeta({
    hasSpecialCase: hasOpenSpecialCase(record),
    isHandover: record.caseCoordination.mode === "handover",
    repairGapKey,
    hasInboundReply: record.communications.some((entry) => entry.direction === "inbound"),
    hasActiveFlow: record.caseFlow.status === "active",
    hasCluster: hasContactClusterOpportunity(record),
    hasSalesRecovery: isViewedWithoutOrder(record),
    hasCommercial: hasCommercialDeskOpportunity(record),
    hasCallbackPressure: Boolean(record.callOps.nextCallbackAt),
    hasFollowupPressure: record.affectedRows.pendingFollowups > 0,
  });
}

function buildOpsRadar(records: CustomerSearchResult[], workboard: CustomerWorkboardSection[]): OpsRadarItem[] {
  const repliesSection = workboard.find((section) => section.key === "recent_replies");
  const callbacksSection = workboard.find((section) => section.key === "callbacks");
  const salesRecoverySection = workboard.find((section) => section.key === "sales_recovery");
  const contactStopsSection = workboard.find((section) => section.key === "contact_stops");
  const viewedWithoutOrder = records.filter((record) => isViewedWithoutOrder(record));
  const missingDesignContext = records.filter(
    (record) => !record.trello || (!record.trello.mockups.length && !record.trello.referenceImage),
  );
  const orderOpenOps = records.filter((record) => hasOrderOpenOps(record));

  return [
    {
      key: "recent_replies",
      label: "Antworten ausstehend",
      count: repliesSection?.results.length || 0,
      detail: "Hier liegt bereits ein Kontaktimpuls vor. Diese Fälle zuerst bearbeiten.",
      lead: repliesSection?.results[0] || null,
      records: repliesSection?.results || [],
      tone: "rose",
    },
    {
      key: "callbacks",
      label: "Rückrufe fällig",
      count: callbacksSection?.results.length || 0,
      detail: "Fälle warten auf Rückmeldung oder einen konkreten Rückruf-Termin.",
      lead: callbacksSection?.results[0] || null,
      records: callbacksSection?.results || [],
      tone: "sky",
    },
    {
      key: "viewed_without_order",
      label: "Rückgewinnung",
      count: viewedWithoutOrder.length,
      detail: "Angebot wurde gesehen, aber es fehlt noch ein klar passender Auftrag. Diese Fälle brauchen Weiterarbeit nah am Abschluss.",
      lead: salesRecoverySection?.results[0] || viewedWithoutOrder[0] || null,
      records: viewedWithoutOrder,
      tone: "amber",
    },
    {
      key: "order_open_ops",
      label: "Auftrag vorhanden, Abschluss fehlt",
      count: orderOpenOps.length,
      detail: "Ein Auftrag ist schon vorhanden, aber Erinnerungen, Rückrufe oder der Fallstand sind noch ausstehend.",
      lead: orderOpenOps[0] || null,
      records: orderOpenOps,
      tone: "emerald",
    },
    {
      key: "missing_design_context",
      label: "Karten- oder Medienlage fehlt",
      count: missingDesignContext.length,
      detail: "Hier fehlt Bild-, Entwurfsbild- oder Kartenlage, obwohl der Fall noch offen ist.",
      lead: missingDesignContext[0] || null,
      records: missingDesignContext,
      tone: "slate",
    },
    {
      key: "contact_stops",
      label: "Kontaktstopps",
      count: contactStopsSection?.results.length || 0,
      detail: "Diese Fälle brauchen besondere Vorsicht, damit nichts mehr automatisch rausgeht.",
      lead: contactStopsSection?.results[0] || null,
      records: contactStopsSection?.results || [],
      tone: "emerald",
    },
  ];
}

function buildOpsMorningBrief({
  inbox,
  workboard,
  radarItems,
  pinnedCases,
}: {
  inbox: CustomerSearchResult[];
  workboard: CustomerWorkboardSection[];
  radarItems: OpsRadarItem[];
  pinnedCases: RecentCase[];
}) {
  const records = dedupeRecords([inbox, ...workboard.map((section) => section.results)]);
  const specialCases = records.filter((record) => hasOpenSpecialCase(record));
  const lines = [
    "NEONTRIP Gesamtlage",
    `Zeitpunkt: ${new Intl.DateTimeFormat("de-DE", { dateStyle: "short", timeStyle: "short" }).format(new Date())}`,
    `Eingang: ${inbox.length} vorrangige Fälle`,
    `Spuren: ${workboard.reduce((sum, section) => sum + section.results.length, 0)} offene Fälle`,
    `Merkliste: ${pinnedCases.length} gemerkte Fälle`,
    `Problemfälle: ${specialCases.length}${specialCases[0] ? ` • Führender Fall: ${specialCases[0].displayName || specialCases[0].request?.title || specialCases[0].requestId}` : ""}`,
    "",
    "Dringlichkeitslage:",
    ...radarItems.map((item) => `- ${item.label}: ${item.count}${item.lead ? ` • Führender Fall: ${item.lead.displayName || item.lead.request?.title || item.lead.requestId}` : ""}`),
    "",
    "Spuren:",
    ...workboard.map(
      (section) =>
        `- ${section.title}: ${section.results.length}${section.results[0] ? ` • Führender Fall: ${section.results[0].displayName || section.results[0].request?.title || section.results[0].requestId}` : ""}`,
    ),
  ];

  return lines.join("\n");
}

function buildCaseListBrief(title: string, records: CustomerSearchResult[]) {
  const lines = [
    title,
    `Stand: ${new Intl.DateTimeFormat("de-DE", { dateStyle: "short", timeStyle: "short" }).format(new Date())}`,
    `Fälle: ${records.length}`,
    "",
  ];

  if (!records.length) {
    lines.push("Aktuell keine Fälle in dieser Liste.");
    return lines.join("\n");
  }

  lines.push(
    ...records.map((record, index) => {
      const parts = [
        `${index + 1}. ${record.displayName || record.request?.title || record.requestId}`,
        record.request?.status || "Stand ausstehend",
        hasOpenSpecialCase(record)
          ? `Problemfall: ${record.specialCase.label || "ungelöst"}${record.specialCase.urgent ? " • dringend" : ""}`
          : null,
        record.caseFlow.status === "active"
          ? `${isActiveFlowStale(record) ? "Ablauf stockt" : "Ablauf läuft"}${getActiveFlowFreshnessLabel(record) ? ` • ${getActiveFlowFreshnessLabel(record)}` : ""}`
          : null,
        record.affectedRows.pendingFollowups > 0 ? `${record.affectedRows.pendingFollowups} Erinnerung ausstehend` : null,
        record.callOps.nextCallbackAt ? `Rückruf ${formatDate(record.callOps.nextCallbackAt)}` : null,
        record.quote?.viewedAt && !record.order ? `Angebot gesehen ${formatDate(record.quote.viewedAt)}` : null,
      ].filter(Boolean);
      return parts.join(" • ");
    }),
  );

  return lines.join("\n");
}

function buildSpecialCaseBrief(record: CustomerSearchResult) {
  const lines = [
    "NEONTRIP Problemfall",
    `Fall: ${record.displayName || record.request?.title || record.requestId}`,
    `Fall-ID: ${record.requestId}`,
    `Typ: ${record.specialCase.label || "Problemfall"}`,
    `Stand: ${record.specialCase.urgent ? "dringend" : "ungelöst"}`,
    `Kontakt: ${record.email}${record.ccEmails.length ? ` • CC: ${record.ccEmails.join(", ")}` : ""}${record.phone ? ` • ${record.phone}` : ""}`,
    `Zuständig: ${record.specialCase.ownerName || record.caseCoordination.ownerName || "noch niemand"}`,
    `Fällig bis: ${record.specialCase.dueAt ? formatDate(record.specialCase.dueAt) : "noch kein Datum gesetzt"}`,
    `Gemeldet: ${formatDate(record.specialCase.reportedAt)}${record.specialCase.reportedBy ? ` • ${record.specialCase.reportedBy}` : ""}`,
    `Hinweis: ${record.specialCase.detail || "Kein zusätzlicher Hinweis."}`,
    `Nächste Aktion: ${getNextBestActionSummary(record).label} • ${getNextBestActionSummary(record).detail}`,
  ];
  return lines.join("\n");
}

function isOpenRequestStatus(value: string | null | undefined) {
  const normalized = String(value || "").trim().toLowerCase();
  if (!normalized) return true;
  return !["won", "lost", "closed", "archived"].includes(normalized);
}

function hasRelatedOpenTriggers(record: CustomerSearchResult) {
  return record.relatedRequests.some((entry) => (entry.pendingFollowups || 0) > 0 || Boolean(entry.nextCallbackAt));
}

function hasRelatedSalesRecovery(record: CustomerSearchResult) {
  return record.relatedRequests.some((entry) => entry.quoteStatus === "viewed" && !entry.orderNumber);
}

function hasMultipleOpenRequests(record: CustomerSearchResult) {
  const currentOpen =
    isOpenRequestStatus(record.request?.status) ||
    record.affectedRows.pendingFollowups > 0 ||
    Boolean(record.callOps.nextCallbackAt);
  const relatedOpen = record.relatedRequests.filter(
    (entry) =>
      isOpenRequestStatus(entry.requestStatus) ||
      isOpenRequestStatus(entry.dealStatus) ||
      (entry.pendingFollowups || 0) > 0 ||
      Boolean(entry.nextCallbackAt),
  ).length;
  return (currentOpen ? 1 : 0) + relatedOpen > 1;
}

function buildContactClusterQueue(records: CustomerSearchResult[]): ContactClusterQueueItem[] {
  const relatedFollowups = records.filter((record) => hasRelatedOpenTriggers(record));
  const relatedSalesRecovery = records.filter((record) => hasRelatedSalesRecovery(record));
  const multiOpenRequests = records.filter((record) => hasMultipleOpenRequests(record));
  const sortedRelatedFollowups = sortRecordsByOpsPriority(relatedFollowups);
  const sortedRelatedSalesRecovery = sortRecordsByOpsPriority(relatedSalesRecovery);
  const sortedMultiOpenRequests = sortRecordsByOpsPriority(multiOpenRequests);
  const resolveContactClusterPreferredTab = (lead: CustomerSearchResult | null): RecordDetailTab =>
    lead ? getNextContactPortfolioFocus(lead)?.tab ?? "contact" : "contact";

  return [
    {
      key: "related_followups" as const,
      title: "Kontaktlage mit offenen Auslösern",
      detail: "Weitere Fälle desselben Kontakts haben ausstehende Erinnerungen oder Rückrufe. Diese Fälle brauchen den Blick aufs ganze Kontaktdossier.",
      tone: "sky" as const,
      records: sortedRelatedFollowups,
      lead: sortedRelatedFollowups[0] || null,
      preferredTab: resolveContactClusterPreferredTab(sortedRelatedFollowups[0] || null),
    },
    {
      key: "related_sales_recovery" as const,
      title: "Kontaktlage mit Kaufsignalen",
      detail: "Ein anderer Fall desselben Kontakts wurde angesehen, aber dort fehlt noch ein Auftrag.",
      tone: "amber" as const,
      records: sortedRelatedSalesRecovery,
      lead: sortedRelatedSalesRecovery[0] || null,
      preferredTab: resolveContactClusterPreferredTab(sortedRelatedSalesRecovery[0] || null),
    },
    {
      key: "multi_open_requests" as const,
      title: "Mehrere Vorgänge gleichzeitig in Arbeit",
      detail: "Für denselben Kontakt laufen mehrere Vorgänge gleichzeitig und sollten gemeinsam bearbeitet werden.",
      tone: "violet" as const,
      records: sortedMultiOpenRequests,
      lead: sortedMultiOpenRequests[0] || null,
      preferredTab: resolveContactClusterPreferredTab(sortedMultiOpenRequests[0] || null),
    },
  ].filter((item) => item.records.length);
}

function buildActiveFlowQueue(records: CustomerSearchResult[]): ActiveFlowQueueItem[] {
  const activeFlowRecords = records.filter((record) => record.caseFlow.status === "active" && record.caseFlow.flowKey);
  const grouped = new Map<string, CustomerSearchResult[]>();

  for (const record of activeFlowRecords) {
    const key = record.caseFlow.flowKey || "other";
    const current = grouped.get(key) || [];
    current.push(record);
    grouped.set(key, current);
  }

  const tones: Record<string, ActiveFlowQueueItem["tone"]> = {
    response: "rose",
    recovery: "emerald",
    repair: "amber",
    contact: "violet",
  };

  return [...grouped.entries()]
    .map(([key, flowRecords]) => {
      const sortedRecords = sortRecordsByOpsPriority(flowRecords);
      const lead = sortedRecords[0] || null;
      const staleCount = sortedRecords.filter((record) => isActiveFlowStale(record)).length;
      return {
        key,
        label: lead?.caseFlow.flowLabel || "Ablauf",
        detail: `${sortedRecords.length} ${sortedRecords.length === 1 ? "aktiver Ablauffall" : "aktive Ablauffälle"} in dieser Spur.${staleCount ? ` ${staleCount} davon sind veraltet.` : ""}`,
        tone: tones[key] || "slate",
        records: sortedRecords,
        staleCount,
      };
    })
    .sort((left, right) => right.staleCount - left.staleCount || right.records.length - left.records.length);
}

function hasOpenSpecialCase(record: CustomerSearchResult) {
  return record.specialCase.status === "open" && Boolean(record.specialCase.kind);
}

function isTechnicalSpecialCase(record: CustomerSearchResult) {
  return record.specialCase.kind === "dimmer_defect" || record.specialCase.kind === "power_supply";
}

function getSpecialCaseDueTime(record: CustomerSearchResult) {
  return record.specialCase.dueAt ? new Date(record.specialCase.dueAt).getTime() : Number.POSITIVE_INFINITY;
}

function isSpecialCaseOverdue(record: CustomerSearchResult) {
  return hasOpenSpecialCase(record) && Boolean(record.specialCase.dueAt) && getSpecialCaseDueTime(record) < Date.now();
}

function getSpecialCaseQueueTone(record: CustomerSearchResult): SpecialCaseQueueItem["tone"] {
  if (isSpecialCaseOverdue(record)) return "rose";
  if (record.specialCase.urgent) return "rose";
  if (record.specialCase.kind === "dimmer_defect" || record.specialCase.kind === "power_supply") return "amber";
  if (record.specialCase.kind === "open_question") return "sky";
  return "slate";
}

type SpecialCasePlaybookAction = RecordDetailTab | "reply" | "callback";

type SpecialCasePlaybook = {
  title: string;
  detail: string;
  steps: string[];
  primary: SpecialCasePlaybookAction;
  primaryLabel: string;
  secondary: RecordDetailTab;
  secondaryLabel: string;
};

function getSpecialCaseProcessMeta(kind: CustomerSearchResult["specialCase"]["kind"] | SpecialCaseDraft["kind"]) {
  switch (kind) {
    case "gift":
      return {
        lane: "Kulanz",
        summary: "Kulanz oder Geschenk klar festhalten und bis zur Bestätigung nicht verlieren.",
        dueDays: 3,
      };
    case "replacement":
      return {
        lane: "Ersatz",
        summary: "Ersatz oder Nachlieferung mit fester Rückmeldung und Termin führen.",
        dueDays: 2,
      };
    case "dimmer_defect":
    case "power_supply":
      return {
        lane: "Technik",
        summary: "Technikthema mit Rückruf, Klärung und Nachverfolgung absichern.",
        dueDays: 1,
      };
    case "open_question":
      return {
        lane: "Rückfrage",
        summary: "Offene Frage mit klarer Antwortspur und Fälligkeit schließen.",
        dueDays: 2,
      };
    default:
      return {
        lane: "Problemfall",
        summary: "Problemfall mit Zuständigkeit, Fälligkeit und nächstem Schritt nachhalten.",
        dueDays: 3,
      };
  }
}

function buildSpecialCaseDefaultDueAt(kind: CustomerSearchResult["specialCase"]["kind"] | SpecialCaseDraft["kind"]) {
  return buildDaysFromNowAt(getSpecialCaseProcessMeta(kind).dueDays, 10);
}

function getSpecialCasePlaybook(record: CustomerSearchResult): SpecialCasePlaybook {
  switch (record.specialCase.kind) {
    case "gift":
      return {
        title: "Kulanz klar festhalten",
        detail: "Geschenk- oder Kulanzfälle brauchen eine klare Zuständigkeit, einen Termin und eine eindeutige Angebotslage.",
        steps: [
          "Zuständig setzen",
          "Fälligkeitsdatum setzen",
          "Angebot oder Verkaufsfall prüfen",
        ],
        primary: "deal" as const,
        primaryLabel: "Angebot prüfen",
        secondary: "history" as const,
        secondaryLabel: "Verlauf öffnen",
      };
    case "replacement":
      return {
        title: "Ersatz klar nachhalten",
        detail: "Ersatz- oder Nachlieferungen brauchen eine klare Rückmeldung und einen festen Termin.",
        steps: [
          "Zuständig setzen",
          "Fälligkeitsdatum setzen",
          "Rückmeldung oder Rückruf auslösen",
        ],
        primary: record.phone?.trim() ? ("callback" as const) : ("communication" as const),
        primaryLabel: record.phone?.trim() ? "Rückruf morgen" : "Antwort öffnen",
        secondary: "history" as const,
        secondaryLabel: "Verlauf öffnen",
      };
    case "dimmer_defect":
    case "power_supply":
      return {
        title: "Technikfall absichern",
        detail: "Defekte oder Netzteilthemen brauchen technischen Rückruf und klare Nachverfolgung.",
        steps: [
          "Zuständig setzen",
          "Fälligkeitsdatum setzen",
          "Technik-Rückruf oder Nachricht auslösen",
        ],
        primary: record.phone?.trim() ? ("callback" as const) : ("communication" as const),
        primaryLabel: record.phone?.trim() ? "Rückruf morgen" : "Antwort öffnen",
        secondary: "sales" as const,
        secondaryLabel: "Vertrieb & Anrufe öffnen",
      };
    case "open_question":
      return {
        title: "Rückfrage klären",
        detail: "Rückfragen sollen eine klare Zuständigkeit, eine Fälligkeit und eine klare Antwortspur bekommen.",
        steps: [
          "Zuständig setzen",
          "Fälligkeitsdatum setzen",
          "Antwort oder Rückruf auslösen",
        ],
        primary: record.email ? ("reply" as const) : ("callback" as const),
        primaryLabel: record.email ? "Jetzt antworten" : "Rückruf morgen",
        secondary: "communication" as const,
        secondaryLabel: "E-Mails öffnen",
      };
    default:
      return {
        title: "Problemfall strukturiert führen",
        detail: "Dieser Problemfall braucht eine klare Zuständigkeit, eine Fälligkeit und einen klaren nächsten Schritt.",
        steps: [
          "Zuständig setzen",
          "Fälligkeitsdatum setzen",
          "Passenden Bereich öffnen",
        ],
        primary: "history" as const,
        primaryLabel: "Verlauf öffnen",
        secondary: "deal" as const,
        secondaryLabel: "Angebot öffnen",
      };
  }
}

function getSpecialCaseQueueDetail(record: CustomerSearchResult) {
  const ownerSuffix = record.specialCase.ownerName ? ` • Zuständig: ${record.specialCase.ownerName}` : "";
  if (record.specialCase.detail && record.specialCase.dueAt) {
    return `${record.specialCase.detail} • Fällig ${formatDate(record.specialCase.dueAt)}${ownerSuffix}`;
  }
  if (record.specialCase.detail) return `${record.specialCase.detail}${ownerSuffix}`;
  if (record.specialCase.dueAt) return `Fällig ${formatDate(record.specialCase.dueAt)}${ownerSuffix}.`;
  switch (record.specialCase.kind) {
    case "gift":
      return `Kulanz- oder Geschenkfall offen und noch nicht eindeutig geklärt${ownerSuffix}.`;
    case "replacement":
      return `Ersatz- oder Nachlieferung offen und braucht eine klare Nachverfolgung${ownerSuffix}.`;
    case "dimmer_defect":
      return `Defekter Dimmer gemeldet und muss nachverfolgt werden${ownerSuffix}.`;
    case "power_supply":
      return `Netzteil-Frage oder Austausch ist offen und darf nicht liegen bleiben${ownerSuffix}.`;
    case "open_question":
      return `Offene Frage ist festgehalten und braucht eine klare Antwort${ownerSuffix}.`;
    default:
      return `Problemfall noch ungelöst${ownerSuffix}.`;
  }
}

function buildSpecialCaseQueue(records: CustomerSearchResult[]): SpecialCaseQueueItem[] {
  const grouped = new Map<NonNullable<CustomerSearchResult["specialCase"]["kind"]>, CustomerSearchResult[]>();

  for (const record of records) {
    if (!hasOpenSpecialCase(record) || !record.specialCase.kind) continue;
    const current = grouped.get(record.specialCase.kind) || [];
    current.push(record);
    grouped.set(record.specialCase.kind, current);
  }

  return [...grouped.entries()]
    .map(([key, caseRecords]) => {
      const sortedRecords = sortRecordsByOpsPriority(caseRecords);
      const lead = sortedRecords[0] || null;
      return {
        key,
        label: lead?.specialCase.label || "Problemfall",
        detail: lead ? getSpecialCaseQueueDetail(lead) : "Problemfall noch ungelöst.",
        tone: lead ? getSpecialCaseQueueTone(lead) : "slate",
        records: sortedRecords,
      };
    })
    .sort((left, right) => right.records.length - left.records.length);
}

function getDominantSpecialCaseKind(records: CustomerSearchResult[]) {
  const counts = new Map<string, number>();
  for (const record of records) {
    if (!hasOpenSpecialCase(record) || !record.specialCase.kind) continue;
    counts.set(record.specialCase.kind, (counts.get(record.specialCase.kind) || 0) + 1);
  }
  const dominant = [...counts.entries()].sort((left, right) => right[1] - left[1])[0]?.[0] || null;
  return dominant as CustomerSearchResult["specialCase"]["kind"] | null;
}

function getSpecialCaseTrackMeta(records: CustomerSearchResult[]) {
  const dominantKind = getDominantSpecialCaseKind(records);
  const process = getSpecialCaseProcessMeta(dominantKind || "other");
  return {
    title:
      process.lane === "Technik"
        ? "Meine Technikfälle"
        : process.lane === "Kulanz"
          ? "Meine Kulanzfälle"
          : process.lane === "Rückfrage"
            ? "Meine Rückfragen"
            : process.lane === "Ersatz"
              ? "Meine Ersatzfälle"
              : "Meine Problemfälle",
    detail: process.summary,
  };
}

function getRepairPriority(record: CustomerSearchResult) {
  const gap = getPrimaryRepairGap(record);
  if (!gap) return 0;
  switch (gap.id) {
    case "blocked_followups":
      return 4;
    case "email_drift":
      return 3;
    case "order_open_ops":
      return 2;
    case "viewed_without_order":
      return 1;
    default:
      return 0;
  }
}

function getSpecialCasePriority(record: CustomerSearchResult) {
  if (!hasOpenSpecialCase(record)) return 0;

  let score = 1;
  if (record.specialCase.kind === "dimmer_defect" || record.specialCase.kind === "power_supply") score += 2;
  if (record.specialCase.kind === "open_question") score += 1;
  if (record.specialCase.urgent) score += 2;
  if (isSpecialCaseOverdue(record)) score += 3;
  return score;
}

function normalizePersonName(value: string | null | undefined) {
  return String(value || "").trim().toLowerCase();
}

function filterRecordsByScope(records: CustomerSearchResult[], scope: QueueScope, operatorName: string) {
  if (scope === "all") return records;
  const normalizedOperator = normalizePersonName(operatorName);
  if (!normalizedOperator) return [];
  if (scope === "mine") {
    return records.filter(
      (record) =>
        normalizePersonName(record.caseCoordination.ownerName) === normalizedOperator &&
        record.caseCoordination.mode !== "handover",
    );
  }
  return records.filter(
    (record) =>
      normalizePersonName(record.caseCoordination.ownerName) === normalizedOperator &&
      record.caseCoordination.mode === "handover",
  );
}

function matchesOpsStatus(record: CustomerSearchResult, filter: OpsStatusFilter) {
  if (filter === "all") return true;
  if (filter === "sales_recovery") {
    return record.salesRecovery.status === "ready" || record.salesRecovery.status === "active";
  }
  if (filter === "closed") {
    return record.opsState.status === "won" || record.opsState.status === "lost";
  }
  return record.opsState.status === filter;
}

function filterRecordsByOpsStatus(records: CustomerSearchResult[], filter: OpsStatusFilter) {
  return records.filter((record) => matchesOpsStatus(record, filter));
}

function compareOpsPriority(left: CustomerSearchResult, right: CustomerSearchResult) {
  const leftHasInbound = left.communications.some((entry) => entry.direction === "inbound");
  const rightHasInbound = right.communications.some((entry) => entry.direction === "inbound");
  if (leftHasInbound !== rightHasInbound) return leftHasInbound ? -1 : 1;

  const leftRepair = getRepairPriority(left);
  const rightRepair = getRepairPriority(right);
  if (leftRepair !== rightRepair) return rightRepair - leftRepair;

  const leftSpecialCasePriority = getSpecialCasePriority(left);
  const rightSpecialCasePriority = getSpecialCasePriority(right);
  if (leftSpecialCasePriority !== rightSpecialCasePriority) return rightSpecialCasePriority - leftSpecialCasePriority;
  if (leftSpecialCasePriority > 0 && rightSpecialCasePriority > 0) {
    const leftUrgent = left.specialCase.urgent;
    const rightUrgent = right.specialCase.urgent;
    if (leftUrgent !== rightUrgent) return leftUrgent ? -1 : 1;
    const leftDueTime = getSpecialCaseDueTime(left);
    const rightDueTime = getSpecialCaseDueTime(right);
    if (leftDueTime !== rightDueTime) return leftDueTime - rightDueTime;
  }

  const leftActiveFlow = left.caseFlow.status === "active";
  const rightActiveFlow = right.caseFlow.status === "active";
  if (leftActiveFlow !== rightActiveFlow) return leftActiveFlow ? -1 : 1;
  const leftStaleFlow = isActiveFlowStale(left);
  const rightStaleFlow = isActiveFlowStale(right);
  if (leftStaleFlow !== rightStaleFlow) return leftStaleFlow ? -1 : 1;

  const leftCallback = Boolean(left.callOps.nextCallbackAt);
  const rightCallback = Boolean(right.callOps.nextCallbackAt);
  if (leftCallback !== rightCallback) return leftCallback ? -1 : 1;

  const leftPending = left.affectedRows.pendingFollowups > 0;
  const rightPending = right.affectedRows.pendingFollowups > 0;
  if (leftPending !== rightPending) return leftPending ? -1 : 1;

  const leftViewedWithoutOrder = Boolean(left.quote?.viewedAt) && !left.order && left.orderDiagnostic.status === "unlinked";
  const rightViewedWithoutOrder = Boolean(right.quote?.viewedAt) && !right.order && right.orderDiagnostic.status === "unlinked";
  if (leftViewedWithoutOrder !== rightViewedWithoutOrder) return leftViewedWithoutOrder ? -1 : 1;

  const leftCommercial = getCommercialPriority(left);
  const rightCommercial = getCommercialPriority(right);
  if (leftCommercial !== rightCommercial) return rightCommercial - leftCommercial;

  const leftCluster = hasContactClusterOpportunity(left);
  const rightCluster = hasContactClusterOpportunity(right);
  if (leftCluster !== rightCluster) return leftCluster ? -1 : 1;

  const leftTrigger = left.callOps.nextCallbackAt || left.affectedRows.nextPendingFollowupAt || left.quote?.viewedAt || left.request?.updatedAt || left.updatedAt;
  const rightTrigger = right.callOps.nextCallbackAt || right.affectedRows.nextPendingFollowupAt || right.quote?.viewedAt || right.request?.updatedAt || right.updatedAt;
  const leftTriggerTime = leftTrigger ? new Date(leftTrigger).getTime() : 0;
  const rightTriggerTime = rightTrigger ? new Date(rightTrigger).getTime() : 0;
  if (leftTriggerTime !== rightTriggerTime) return leftTriggerTime - rightTriggerTime;

  const leftUpdated = new Date(left.request?.updatedAt || left.updatedAt || 0).getTime();
  const rightUpdated = new Date(right.request?.updatedAt || right.updatedAt || 0).getTime();
  return rightUpdated - leftUpdated;
}

function sortRecordsByOpsPriority(records: CustomerSearchResult[]) {
  return [...records].sort(compareOpsPriority);
}

type NextBestActionKey =
  | "stop_contact"
  | "repair_sync"
  | "mark_won"
  | "special_case"
  | "reply"
  | "resume_flow"
  | "callback"
  | "followup"
  | "sales_recovery"
  | "commercial_desk"
  | "contact_dossier"
  | "review_context";

type NextBestActionSummary = {
  key: NextBestActionKey;
  label: string;
  detail: string;
};

function getNextBestActionSummary(record: CustomerSearchResult): NextBestActionSummary {
  const repairGap = getPrimaryRepairGap(record);
  if (repairGap?.id === "blocked_followups") {
    return {
      key: "stop_contact",
      label: "Folgeprozess stoppen",
      detail: "Kontaktstopp passt noch nicht zu den offenen Erinnerungen.",
    };
  }

  if (repairGap?.id === "email_drift") {
    return {
      key: "repair_sync",
      label: "Abgleich weicht ab",
      detail: "Führender Kontakt und weitere Systeme verwenden nicht dieselbe E-Mail.",
    };
  }

  if (repairGap?.id === "order_open_ops") {
    return {
      key: "mark_won",
      label: "Als gewonnen schließen",
      detail: "Ein Auftrag ist schon da, aber der Fall ist noch nicht als gewonnen abgeschlossen.",
    };
  }

  if (hasOpenSpecialCase(record)) {
    const parts = [getSpecialCaseQueueDetail(record)];
    if (record.specialCase.ownerName && !parts[0].includes("Zuständig:")) {
      parts.push(`Zuständig: ${record.specialCase.ownerName}`);
    }
    return {
      key: "special_case",
      label: isSpecialCaseOverdue(record) ? "Problemfall überfällig" : "Problemfall klären",
      detail: parts.filter(Boolean).join(" • "),
    };
  }

  if (record.communications.some((entry) => entry.direction === "inbound")) {
    return {
      key: "reply",
      label: "Antwort ausstehend",
      detail: "Kontakt hat bereits reagiert. Das ist der schnellste Ansatz.",
    };
  }

  if (record.caseFlow.status === "active") {
    if (isActiveFlowStale(record)) {
      return {
        key: "resume_flow",
        label: "Ablauf reaktivieren",
        detail: `${record.caseFlow.flowLabel || "Ablauf"} stockt${getActiveFlowFreshnessLabel(record) ? ` • ${getActiveFlowFreshnessLabel(record)}` : ""}. Erst fortsetzen, dann neue Fälle ziehen.`,
      };
    }
    return {
      key: "resume_flow",
      label: "Im Ablauf weitermachen",
      detail: `${record.caseFlow.flowLabel || "Ablauf"} läuft bereits${record.caseFlow.currentStepLabel ? ` • nächster Schritt: ${record.caseFlow.currentStepLabel}` : ""}.`,
    };
  }

  if (record.callOps.nextCallbackAt) {
    return {
      key: "callback",
      label: "Rückruf fällig",
      detail: `Rückruf geplant für ${formatDate(record.callOps.nextCallbackAt)}.`,
    };
  }

  if (record.affectedRows.pendingFollowups > 0) {
    return {
      key: "followup",
      label: "Erinnerung fällig",
      detail: record.affectedRows.nextPendingFollowupAt
        ? `Nächster Versand ${formatDate(record.affectedRows.nextPendingFollowupAt)}.`
        : `${record.affectedRows.pendingFollowups} offene Erinnerung${record.affectedRows.pendingFollowups === 1 ? "" : "en"}.`,
    };
  }

  if (record.quote?.viewedAt && !record.order && record.orderDiagnostic.status === "unlinked") {
    return {
      key: "sales_recovery",
      label: "Rückgewinnung",
      detail: `Angebot wurde gesehen am ${formatDate(record.quote.viewedAt)}.`,
    };
  }

  if (hasCommercialDeskOpportunity(record)) {
    const commercialSummary = getCommercialDeskSummary(record);
    if (commercialSummary.key === "crm_builder") {
      return {
        key: "commercial_desk",
        label: "Abschlussspur",
        detail: "Angebotslage ist aktiv und sollte in der Verkaufs- und Herkunftslage weitergeführt werden.",
      };
    }

    if (commercialSummary.key === "live_quotes") {
      return {
        key: "commercial_desk",
        label: "Abschlussspur",
        detail: "Aktive Verkaufs- oder Angebotslage ist vorhanden und sollte in der Abschlussspur weitergeführt werden.",
      };
    }
  }

  const clusterLabel = getPrimaryContactClusterLabel(record);
  if (clusterLabel === "Offene Signale im Kontakt") {
    return {
      key: "contact_dossier",
      label: "Kontaktdossier",
      detail: "Im Kontakt laufen weitere Fälle mit offenem Erinnerungs- oder Rückrufdruck und sollten gemeinsam bearbeitet werden.",
    };
  }

  if (clusterLabel === "Kaufsignal im Kontaktdossier") {
    return {
      key: "contact_dossier",
      label: "Kontaktdossier",
      detail: "Ein weiterer Fall zeigt bereits ein Kaufinteresse und sollte im Dossier gemeinsam statt isoliert bearbeitet werden.",
    };
  }

  if (clusterLabel === "Mehrere Fälle") {
    return {
      key: "contact_dossier",
      label: "Kontaktdossier",
      detail: "Mehrere offene Fälle desselben Kontakts sollten als gemeinsames Dossier geprüft und koordiniert werden.",
    };
  }

  return {
    key: "review_context",
    label: "Lage prüfen",
    detail: record.request?.status || "Fall ohne akute Fälligkeit, aber mit offenem Klärungsbedarf.",
  };
}

function toSimpleActionLabel(summary: NextBestActionSummary) {
  switch (summary.key) {
    case "special_case":
      return "Problem klären";
    case "stop_contact":
      return "Kontakt beenden";
    case "repair_sync":
      return "Daten angleichen";
    case "reply":
      return "Antwort ausstehend";
    case "resume_flow":
      return "Im Ablauf weitermachen";
    case "callback":
      return "Rückruf fällig";
    case "followup":
      return "Erinnerung fällig";
    case "sales_recovery":
      return "Angebot nachfassen";
    case "commercial_desk":
      return "Angebot prüfen";
    case "contact_dossier":
      return "Weiteren Fall prüfen";
    case "review_context":
      return "Kurz prüfen";
    default:
      return summary.label;
  }
}

function toSimpleActionDetail(summary: NextBestActionSummary) {
  if (summary.key === "special_case") {
    return summary.detail || "Hier ist ein gemeldeter Problemfall, der nicht vergessen werden darf.";
  }

  if (summary.key === "followup") {
    return summary.detail
      .replace("Nächster Versand", "Nächste Erinnerung")
      .replace("offene Follow-up", "offene Erinnerung")
      .replace(" offenen Follow-ups", " offenen Erinnerungen");
  }

  if (summary.key === "repair_sync") {
    return "Die gespeicherten Kontaktdaten sind nicht überall gleich.";
  }

  if (summary.key === "contact_dossier") {
    return "Zu diesem Kontakt gibt es noch eine weitere wichtige Anfrage.";
  }

  return summary.detail;
}

function getNextBestActionTone(record: CustomerSearchResult) {
  const repairGap = getPrimaryRepairGap(record);
  if (repairGap?.id === "blocked_followups") {
    return "border-rose-200 bg-rose-50 text-rose-950";
  }

  if (repairGap?.id === "email_drift") {
    return "border-rose-200 bg-rose-50 text-rose-950";
  }

  if (repairGap?.id === "order_open_ops") {
    return "border-emerald-200 bg-emerald-50 text-emerald-950";
  }

  if (hasOpenSpecialCase(record)) {
    return record.specialCase.urgent
      ? "border-rose-200 bg-rose-50 text-rose-950"
      : "border-amber-200 bg-amber-50 text-amber-950";
  }

  if (record.communications.some((entry) => entry.direction === "inbound")) {
    return "border-[#fa31a2]/20 bg-[#fff3fa] text-[#571333]";
  }

  if (record.caseFlow.status === "active") {
    return isActiveFlowStale(record)
      ? "border-amber-200 bg-amber-50 text-amber-950"
      : "border-violet-200 bg-violet-50 text-violet-950";
  }

  if (record.callOps.nextCallbackAt) {
    return "border-sky-200 bg-sky-50 text-sky-950";
  }

  if (record.affectedRows.pendingFollowups > 0) {
    return "border-amber-200 bg-amber-50 text-amber-950";
  }

  if (record.quote?.viewedAt && !record.order && record.orderDiagnostic.status === "unlinked") {
    return "border-emerald-200 bg-emerald-50 text-emerald-950";
  }

  if (hasCommercialDeskOpportunity(record)) {
    const commercialSummary = getCommercialDeskSummary(record);
    if (commercialSummary.key === "crm_builder") {
      return "border-violet-200 bg-violet-50 text-violet-950";
    }

    if (commercialSummary.key === "live_quotes") {
      return "border-sky-200 bg-sky-50 text-sky-950";
    }
  }

  if (hasContactClusterOpportunity(record)) {
    return "border-violet-200 bg-violet-50 text-violet-950";
  }

  return "border-slate-200 bg-slate-50 text-slate-950";
}

function getPrimaryRepairGap(record: CustomerSearchResult) {
  return getSystemGapItems(record).find((gap) =>
    gap.id === "blocked_followups" ||
    gap.id === "email_drift" ||
    gap.id === "order_open_ops" ||
    gap.id === "viewed_without_order",
  ) || null;
}

function getPrimaryContactClusterLabel(record: CustomerSearchResult) {
  if (hasRelatedOpenTriggers(record)) {
    return "Offene Signale im Kontakt";
  }
  if (hasRelatedSalesRecovery(record)) {
    return "Kaufsignal im Kontaktdossier";
  }
  if (hasMultipleOpenRequests(record)) {
    return "Mehrere Fälle";
  }
  return null;
}

function hasContactClusterOpportunity(record: CustomerSearchResult) {
  return Boolean(getPrimaryContactClusterLabel(record));
}

function buildCasePlan(record: CustomerSearchResult): CasePlanStep[] {
  const steps: CasePlanStep[] = [];
  const seen = new Set<string>();
  const latestInbound = record.communications.find((entry) => entry.direction === "inbound") || null;
  const repairGap = getPrimaryRepairGap(record);
  const systemGaps = getSystemGapItems(record);

  function pushStep(step: CasePlanStep | null) {
    if (!step || seen.has(step.key)) return;
    seen.add(step.key);
    steps.push(step);
  }

  if (repairGap?.id === "blocked_followups") {
    pushStep({
      key: "repair-blocked-followups",
      label: "Kontaktstopp vollständig durchziehen",
      detail: repairGap.detail,
      tab: "history",
      tone: "rose",
      actionLabel: "Erinnerungen stoppen",
      action: "pause_followups",
    });
  } else if (repairGap?.id === "email_drift") {
    pushStep({
      key: "repair-email-drift",
      label: "Weitere Systeme angleichen",
      detail: repairGap.detail,
      tab: "contact",
      tone: "rose",
      actionLabel: "Abgleich beheben",
      action: "repair_downstream_sync",
    });
  } else if (repairGap?.id === "order_open_ops") {
    pushStep({
      key: "repair-order-open-ops",
      label: "Gewonnen korrekt abschließen",
      detail: repairGap.detail,
      tab: "history",
      tone: "emerald",
      actionLabel: "Als gewonnen schließen",
      action: "mark_won",
    });
  }

  if (latestInbound) {
    pushStep({
      key: "reply-inbound",
      label: "Auf die letzte eingehende Mail reagieren",
      detail: latestInbound.title || "Es liegt eine eingehende Antwort im Kommunikationsverlauf.",
      tab: "communication",
      tone: "rose",
      actionLabel: "Jetzt antworten",
      action: "reply",
    });
  }

  const callbackNoPhoneGap = systemGaps.find((gap) => gap.id === "callback_no_phone");
  if (callbackNoPhoneGap) {
    pushStep({
      key: "callback-no-phone",
      label: "Rückruf erst absichern",
      detail: callbackNoPhoneGap.detail,
      tab: "contact",
      tone: "slate",
      actionLabel: "Telefonnummer ergänzen",
      action: "open",
    });
  } else if (record.callOps.nextCallbackAt) {
    pushStep({
      key: "callback-open",
      label: "Rückruf priorisiert abarbeiten",
      detail: `Rückruf ist für ${formatDate(record.callOps.nextCallbackAt)} geplant.`,
      tab: "sales",
      tone: "sky",
      actionLabel: "Rückruf morgen",
      action: "schedule_callback",
    });
  }

  if (record.affectedRows.pendingFollowups > 0) {
    pushStep({
      key: "followup-open",
      label: "Folgeprozess weiterführen",
      detail: record.affectedRows.nextPendingFollowupAt
        ? `Nächster Versand ist für ${formatDate(record.affectedRows.nextPendingFollowupAt)} geplant.`
        : `${record.affectedRows.pendingFollowups} Erinnerung${record.affectedRows.pendingFollowups === 1 ? "" : "en"} sind offen.`,
      tab: "history",
      tone: "amber",
      actionLabel: "Erinnerung auf morgen",
      action: "reschedule_followups",
    });
  }

  const viewedWithoutOrderGap = systemGaps.find((gap) => gap.id === "viewed_without_order");
  if (viewedWithoutOrderGap) {
    pushStep({
      key: "sales-recovery",
      label: record.phone?.trim() ? "Kaufsignal in die Rückgewinnung überführen" : "Kaufsignal im Vertriebskontext prüfen",
      detail: viewedWithoutOrderGap.detail,
      tab: "sales",
      tone: "emerald",
      actionLabel: record.phone?.trim() ? "Rückgewinnung starten" : "Verkaufsdaten öffnen",
      action: record.phone?.trim() ? "start_sales_recovery" : "open",
    });
  }

  if (hasCommercialDeskOpportunity(record)) {
    const commercialSummary = getCommercialDeskSummary(record);
    pushStep({
      key: `commercial-${commercialSummary.key}`,
      label: "Verkaufs- und Angebotslage bündeln",
      detail: commercialSummary.detail,
      tab: "deal",
      tone: commercialSummary.key === "crm_builder" ? "violet" : "sky",
      actionLabel: "Abschlussspur",
      action: "open_commercial_desk",
    });
  }

  if (hasContactClusterOpportunity(record)) {
    pushStep({
      key: "contact-dossier",
      label: "Kontaktweit statt isoliert arbeiten",
      detail: getNextBestActionSummary(record).key === "contact_dossier"
        ? getNextBestActionSummary(record).detail
        : "Am Kontakt laufen weitere relevante Fälle, die zusammen geprüft werden sollten.",
      tab: "deal",
      tone: "violet",
      actionLabel: "Kontaktdossier",
      action: "open_contact_dossier",
    });
  }

  const trelloGap = systemGaps.find((gap) => gap.id === "trello_context_thin");
  if (trelloGap) {
    pushStep({
      key: "trello-context",
      label: "Medienlage nachziehen",
      detail: trelloGap.detail,
      tab: "trello",
      tone: "amber",
      actionLabel: "Karten prüfen",
      action: "open",
    });
  }

  const outboundOnlyGap = systemGaps.find((gap) => gap.id === "outbound_only_followup");
  if (outboundOnlyGap) {
    pushStep({
      key: "communication-context",
      label: "Kommunikationslage prüfen",
      detail: outboundOnlyGap.detail,
      tab: "communication",
      tone: "slate",
      actionLabel: "Kommunikation",
      action: "open",
    });
  }

  if (!steps.length) {
    pushStep({
      key: "steady-state",
      label: "Lage einmal ruhig prüfen",
      detail: "Der Fall wirkt derzeit stabil. Prüfe Verkaufs-, Kommunikations- und Auslöserlage einmal gesammelt, bevor du aktiv eingreifst.",
      tab: inferPreferredTab(record),
      tone: "slate",
      actionLabel: getRecordTabOpenLabel(inferPreferredTab(record)),
      action: "open",
    });
  }

  return steps.slice(0, 4);
}

function buildCaseFlows(record: CustomerSearchResult): CaseFlow[] {
  const steps = buildCasePlan(record);
  const byKey = new Map(steps.map((step) => [step.key, step] as const));
  const flows: CaseFlow[] = [];

  function pick(...keys: string[]) {
    return keys
      .map((key) => byKey.get(key))
      .filter((step): step is CasePlanStep => Boolean(step));
  }

  const responseSteps = pick("reply-inbound", "contact-dossier", "followup-open", "communication-context");
  if (responseSteps.length) {
    flows.push({
      key: "response",
      title: "Antwort-Ablauf",
      detail: "Antworten, Lage sichern und den nächsten Folgeprozess neu aufsetzen.",
      tone: "rose",
      steps: responseSteps,
    });
  }

  const recoverySteps = pick("sales-recovery", "callback-open", "commercial-live_quotes", "commercial-crm_builder");
  if (recoverySteps.length) {
    flows.push({
      key: "recovery",
      title: "Rückgewinnungsablauf",
      detail: "Kaufsignal in die Rückgewinnung überführen, Rückruf setzen und die Verkaufs- oder Angebotsdaten mitziehen.",
      tone: "emerald",
      steps: recoverySteps,
    });
  }

  const repairSteps = pick("repair-email-drift", "repair-blocked-followups", "repair-order-open-ops", "trello-context");
  if (repairSteps.length) {
    flows.push({
      key: "repair",
      title: "Reparatur-Ablauf",
      detail: "Systemfehler zuerst beheben, bevor der Fall weiter in anderen Spuren oder im Vertrieb läuft.",
      tone: "amber",
      steps: repairSteps,
    });
  }

  const contactSteps = pick("contact-dossier", "commercial-live_quotes", "commercial-crm_builder", "followup-open");
  if (contactSteps.length >= 2) {
    flows.push({
      key: "contact",
      title: "Ablauf im Kontaktdossier",
      detail: "Kontakte mit mehreren Fällen nicht isoliert, sondern als gemeinsames Dossier bearbeiten.",
      tone: "violet",
      steps: contactSteps,
    });
  }

  return flows;
}

function RecommendedActionInline({
  record,
}: {
  record: CustomerSearchResult;
}) {
  const recommendation = getNextBestActionSummary(record);
  const tone = getNextBestActionTone(record);
  const hasFlowState = record.caseFlow.status !== "idle";

  return (
    <div className={`mt-3 rounded-xl border px-3 py-3 ${tone}`}>
      <div className="flex items-center justify-between gap-3">
        <div className="text-[10px] uppercase tracking-[0.14em] opacity-70">Empfohlen</div>
        <span className="rounded-full border border-current/15 bg-white/55 px-2.5 py-1 text-[10px] uppercase tracking-[0.14em]">
          {recommendation.label}
        </span>
      </div>
      <div className="mt-2 text-sm leading-6 opacity-80">{recommendation.detail}</div>
      {hasFlowState ? (
        <div className="mt-3 flex flex-wrap items-center gap-2">
          <span className="rounded-full border border-current/15 bg-white/65 px-2.5 py-1 text-[10px] uppercase tracking-[0.14em]">
            Ablauf
          </span>
          <ActiveFlowFreshnessPill record={record} />
          <span className="text-xs opacity-75">
            {record.caseFlow.flowLabel || "Ablauf"} • {record.caseFlow.completedCount}
            {record.caseFlow.totalSteps ? `/${record.caseFlow.totalSteps}` : ""} Schritte
          </span>
        </div>
      ) : null}
    </div>
  );
}

function SimpleSpecialCaseFlag({
  record,
}: {
  record: CustomerSearchResult;
}) {
  if (!hasOpenSpecialCase(record)) return null;
  const process = getSpecialCaseProcessMeta(record.specialCase.kind);

  return (
    <div className={`mt-3 rounded-xl border px-3 py-3 ${
      record.specialCase.urgent || isSpecialCaseOverdue(record)
        ? "border-rose-200 bg-rose-50 text-rose-950"
        : "border-amber-200 bg-amber-50 text-amber-950"
    }`}>
      <div className="flex flex-wrap items-center justify-between gap-2">
        <div className="text-[10px] uppercase tracking-[0.14em] opacity-70">Problemfall</div>
        <span className="rounded-full border border-current/15 bg-white/70 px-2.5 py-1 text-[10px] uppercase tracking-[0.14em]">
          {record.specialCase.urgent ? "dringend" : isSpecialCaseOverdue(record) ? "überfällig" : "offen"}
        </span>
      </div>
      <div className="mt-2 text-sm font-semibold">{record.specialCase.label || "Ungelöster Problemfall"}</div>
      <div className="mt-1 text-sm leading-6 opacity-80">{getSpecialCaseQueueDetail(record)}</div>
      <div className="mt-2 text-xs opacity-70">
        Pfad: {process.lane} • {process.summary}
      </div>
    </div>
  );
}

function executeCasePlanStep({
  record,
  step,
  surface,
  onPauseFollowups,
  onRepairDownstreamSync,
  onStartSalesRecovery,
  onApplyOutcome,
  onRescheduleFollowups,
  onScheduleCallback,
  onOpenTab,
  onOpenRecord,
  onOpenContactPortfolio,
  onOpenCommercialDesk,
}: {
  record: CustomerSearchResult;
  step: CasePlanStep;
  surface: string;
  onPauseFollowups: (requestId: string) => Promise<void>;
  onRepairDownstreamSync: (requestId: string) => Promise<void>;
  onStartSalesRecovery: (requestId: string, reason: string) => Promise<void>;
  onApplyOutcome: (requestId: string, outcome: CaseOutcomeDraft) => Promise<void>;
  onRescheduleFollowups: (requestId: string, resumeAt: string, reason: string) => Promise<void>;
  onScheduleCallback: (requestId: string, resumeAt: string, reason: string) => Promise<void>;
  onOpenTab?: (tab: RecordDetailTab) => void;
  onOpenRecord?: (tab: RecordDetailTab) => void;
  onOpenContactPortfolio?: () => void;
  onOpenCommercialDesk?: () => void;
}) {
  if (step.action === "reply") {
    const latestInbound = record.communications.find((entry) => entry.direction === "inbound") || null;
    window.open(
      buildOutlookComposeUrl(
        record.email,
        record.displayName,
        latestInbound?.title ? `Re: ${latestInbound.title}` : `Re: ${record.displayName || "NEONTRIP Anfrage"}`,
      ),
      "_blank",
      "noopener,noreferrer",
    );
    return;
  }
  if (step.action === "repair_downstream_sync") {
    void onRepairDownstreamSync(record.requestId);
    return;
  }
  if (step.action === "pause_followups") {
    void onPauseFollowups(record.requestId);
    return;
  }
  if (step.action === "start_sales_recovery") {
    void onStartSalesRecovery(record.requestId, `Direkt aus ${surface} in die Rückgewinnung überführt.`);
    return;
  }
  if (step.action === "mark_won") {
    void onApplyOutcome(record.requestId, {
      outcome: "won",
      resumeAt: "",
      reason: `Direkt aus ${surface} als gewonnen abgeschlossen.`,
    });
    return;
  }
  if (step.action === "reschedule_followups") {
    void onRescheduleFollowups(record.requestId, buildTomorrowAt(10), `Direkt aus ${surface} auf morgen verschoben.`);
    return;
  }
  if (step.action === "schedule_callback") {
    void onScheduleCallback(record.requestId, buildTomorrowAt(10), `Direkt aus ${surface} auf morgen gesetzt.`);
    return;
  }
  if (step.action === "open_contact_dossier" && onOpenContactPortfolio) {
    onOpenContactPortfolio();
    return;
  }
  if (step.action === "open_commercial_desk" && onOpenCommercialDesk) {
    onOpenCommercialDesk();
    return;
  }
  if (step.action === "open" || step.action === "open_contact_dossier" || step.action === "open_commercial_desk") {
    if (onOpenRecord) {
      onOpenRecord(step.tab);
      return;
    }
    if (onOpenTab) {
      onOpenTab(step.tab);
    }
  }
}

function InlineCaseFlowAssist({
  record,
  surface,
  actionRunning,
  onPauseFollowups,
  onRepairDownstreamSync,
  onStartSalesRecovery,
  onApplyOutcome,
  onRescheduleFollowups,
  onScheduleCallback,
  onOpenRecord,
  onOpenContactPortfolio,
  onOpenCommercialDesk,
}: {
  record: CustomerSearchResult;
  surface: string;
  actionRunning: boolean;
  onPauseFollowups: (requestId: string) => Promise<void>;
  onRepairDownstreamSync: (requestId: string) => Promise<void>;
  onStartSalesRecovery: (requestId: string, reason: string) => Promise<void>;
  onApplyOutcome: (requestId: string, outcome: CaseOutcomeDraft) => Promise<void>;
  onRescheduleFollowups: (requestId: string, resumeAt: string, reason: string) => Promise<void>;
  onScheduleCallback: (requestId: string, resumeAt: string, reason: string) => Promise<void>;
  onOpenRecord: (tab: RecordDetailTab) => void;
  onOpenContactPortfolio?: () => void;
  onOpenCommercialDesk?: () => void;
}) {
  const flows = buildCaseFlows(record);
  const { getProgress, setLastFlowKey, markCompleted, resetProgress } = useCaseFlowProgress();
  const [activeFlowKey, setActiveFlowKey] = useState<CaseFlow["key"] | null>(null);
  const flowProgress = resolveCaseFlowProgress(record, getProgress(record.requestId));
  const completedKeys = flowProgress.completedKeys;
  const activeFlow = flows.find((flow) => flow.key === activeFlowKey) || null;
  const leadFlow =
    activeFlow ||
    flows.find((flow) => flow.key === flowProgress.lastFlowKey) ||
    flows.find((flow) => flow.steps.some((step) => !completedKeys.includes(step.key))) ||
    flows[0] ||
    null;
  const nextFlowStep = leadFlow?.steps.find((step) => !completedKeys.includes(step.key)) || null;
  const completedCount = leadFlow ? leadFlow.steps.filter((step) => completedKeys.includes(step.key)).length : 0;
  const toneClass: Record<CaseFlow["tone"], string> = {
    rose: "border-rose-200 bg-rose-50 text-rose-950",
    amber: "border-amber-200 bg-amber-50 text-amber-950",
    emerald: "border-emerald-200 bg-emerald-50 text-emerald-950",
    sky: "border-sky-200 bg-sky-50 text-sky-950",
    violet: "border-violet-200 bg-violet-50 text-violet-950",
    slate: "border-slate-200 bg-slate-50 text-slate-950",
  };

  useEffect(() => {
    setActiveFlowKey(null);
  }, [record.requestId]);

  if (!flows.length || !leadFlow) return null;

  function markStepDone(step: CasePlanStep) {
    markCompleted(record.requestId, { key: step.key, label: step.label }, leadFlow, leadFlow.steps.length);
  }

  function runStep(step: CasePlanStep) {
    executeCasePlanStep({
      record,
      step,
      surface,
      onPauseFollowups,
      onRepairDownstreamSync,
      onStartSalesRecovery,
      onApplyOutcome,
      onRescheduleFollowups,
      onScheduleCallback,
      onOpenRecord,
      onOpenContactPortfolio,
      onOpenCommercialDesk,
    });
    markStepDone(step);
  }

  return (
    <>
      <div className="flex flex-wrap items-center gap-2">
        <span className={`rounded-full border px-2.5 py-1 text-[10px] uppercase tracking-[0.14em] ${toneClass[leadFlow.tone]}`}>
          {leadFlow.title} • {completedCount}/{leadFlow.steps.length}
        </span>
        <button
          type="button"
          onClick={() => {
            if (!nextFlowStep) {
              resetProgress(record.requestId, leadFlow, leadFlow.steps.length);
            } else {
              setLastFlowKey(record.requestId, leadFlow, leadFlow.steps.length);
            }
            setActiveFlowKey(leadFlow.key);
          }}
          className="rounded-full border border-black/10 bg-white px-3 py-2 text-xs font-medium text-black/65 transition hover:border-[#fa31a2] hover:text-black"
        >
          {nextFlowStep ? (completedCount ? "Im Ablauf weitermachen" : "Ablauf starten") : "Ablauf neu starten"}
        </button>
      </div>
      <Modal
        open={Boolean(activeFlowKey)}
        onClose={() => setActiveFlowKey(null)}
        title={leadFlow.title}
        subtitle={`${leadFlow.detail} • ${record.displayName || record.request?.title || record.requestId}`}
      >
        <div className="space-y-5">
          <div className="rounded-2xl border border-black/10 bg-black/[0.02] p-4 text-sm leading-7 text-black/65">
            Dieser Ablauf nutzt nur die bestehenden sicheren Arbeitsaktionen der Zentrale. Er bündelt sie für diesen Fall als kurzen Arbeitslauf.
          </div>
          <div className="space-y-3">
            {leadFlow.steps.map((step, index) => {
              const done = completedKeys.includes(step.key);
              const current = !done && nextFlowStep?.key === step.key;
              return (
                <div
                  key={`inline-flow-${record.requestId}-${step.key}`}
                  className={`rounded-2xl border p-4 ${toneClass[leadFlow.tone]} ${current ? "ring-1 ring-[#fa31a2]/30" : ""} ${done ? "opacity-75" : ""}`}
                >
                  <div className="flex items-start gap-3">
                    <div className="flex h-8 w-8 shrink-0 items-center justify-center rounded-full border border-current/15 bg-white/70 text-xs font-semibold">
                      {done ? "✓" : index + 1}
                    </div>
                    <div className="min-w-0 flex-1">
                      <div className="flex flex-wrap items-center gap-2">
                        <div className="text-sm font-semibold">{step.label}</div>
                        <span className="rounded-full border border-current/15 bg-white/70 px-2.5 py-1 text-[10px] uppercase tracking-[0.14em]">
                          {done ? "erledigt" : current ? "jetzt" : "danach"}
                        </span>
                      </div>
                      <div className="mt-2 text-sm leading-6 opacity-80">{step.detail}</div>
                      <div className="mt-3 flex flex-wrap gap-2">
                        <button
                          type="button"
                          disabled={actionRunning || done}
                          onClick={() => runStep(step)}
                          className="rounded-full border border-current/15 bg-white/80 px-3 py-2 text-xs font-medium transition hover:bg-white disabled:cursor-not-allowed disabled:opacity-50"
                        >
                          {done ? "Schon ausgeführt" : step.actionLabel}
                        </button>
                        {!done ? (
                          <button
                            type="button"
                            onClick={() => markStepDone(step)}
                            className="rounded-full border border-current/15 bg-white/55 px-3 py-2 text-xs font-medium transition hover:bg-white"
                          >
                            Als erledigt markieren
                          </button>
                        ) : null}
                      </div>
                    </div>
                  </div>
                </div>
              );
            })}
          </div>
          <div className="flex flex-wrap justify-end gap-3">
            {nextFlowStep ? (
              <button
                type="button"
                disabled={actionRunning}
                onClick={() => runStep(nextFlowStep)}
                className="inline-flex items-center gap-2 rounded-full bg-[#0A0A0A] px-5 py-2.5 text-sm font-medium text-white transition hover:bg-black/90 disabled:cursor-not-allowed disabled:bg-black/20"
              >
                Im Ablauf weitermachen
                <ArrowRight className="h-4 w-4" />
              </button>
            ) : (
              <div className="rounded-full border border-emerald-200 bg-emerald-50 px-4 py-2 text-sm font-medium text-emerald-900">
                Ablauf für diese Lage durchgearbeitet
              </div>
            )}
          </div>
        </div>
      </Modal>
    </>
  );
}

function RecommendedPrimaryAction({
  record,
  surface,
  runningRequestId,
  onRescheduleFollowups,
  onScheduleCallback,
  onStartSalesRecovery,
  onPauseFollowups,
  onRepairDownstreamSync,
  onApplyOutcome,
  onOpenContactPortfolio,
  onOpenCommercialDesk,
  showFlowAssist = false,
  onOpenRecord,
}: {
  record: CustomerSearchResult;
  surface: string;
  runningRequestId: string | null;
  onRescheduleFollowups: (requestId: string, resumeAt: string, reason: string) => Promise<void>;
  onScheduleCallback: (requestId: string, resumeAt: string, reason: string) => Promise<void>;
  onStartSalesRecovery: (requestId: string, reason: string) => Promise<void>;
  onPauseFollowups: (requestId: string) => Promise<void>;
  onRepairDownstreamSync: (requestId: string) => Promise<void>;
  onApplyOutcome: (requestId: string, outcome: CaseOutcomeDraft) => Promise<void>;
  onOpenContactPortfolio?: () => void;
  onOpenCommercialDesk?: () => void;
  showFlowAssist?: boolean;
  onOpenRecord?: (tab: RecordDetailTab) => void;
}) {
  const repairGap = getPrimaryRepairGap(record);
  const hasFlowAssist = showFlowAssist && Boolean(onOpenRecord) && buildCaseFlows(record).length > 0;

  function renderWithFlow(primaryAction: ReactNode | null) {
    if (!primaryAction && !hasFlowAssist) return null;
    return (
      <div className="flex flex-wrap items-center gap-2">
        {primaryAction}
        {hasFlowAssist && onOpenRecord ? (
          <InlineCaseFlowAssist
            record={record}
            surface={surface}
            actionRunning={runningRequestId === record.requestId}
            onPauseFollowups={onPauseFollowups}
            onRepairDownstreamSync={onRepairDownstreamSync}
            onStartSalesRecovery={onStartSalesRecovery}
            onApplyOutcome={onApplyOutcome}
            onRescheduleFollowups={onRescheduleFollowups}
            onScheduleCallback={onScheduleCallback}
            onOpenRecord={onOpenRecord}
            onOpenContactPortfolio={onOpenContactPortfolio}
            onOpenCommercialDesk={onOpenCommercialDesk}
          />
        ) : null}
      </div>
    );
  }

  if (repairGap?.id === "blocked_followups") {
    return renderWithFlow(
      <button
        type="button"
        disabled={runningRequestId === record.requestId}
        onClick={() => void onPauseFollowups(record.requestId)}
        className="inline-flex items-center gap-2 rounded-full bg-[#0A0A0A] px-4 py-2.5 text-sm font-medium text-white transition hover:bg-black/90 disabled:cursor-not-allowed disabled:bg-black/20"
      >
        Erinnerungen stoppen
        <ArrowRight className="h-4 w-4" />
      </button>
    );
  }

  if (repairGap?.id === "email_drift") {
    return renderWithFlow(
      <button
        type="button"
        disabled={runningRequestId === record.requestId}
        onClick={() => void onRepairDownstreamSync(record.requestId)}
        className="inline-flex items-center gap-2 rounded-full bg-[#0A0A0A] px-4 py-2.5 text-sm font-medium text-white transition hover:bg-black/90 disabled:cursor-not-allowed disabled:bg-black/20"
      >
        Abgleich beheben
        <ArrowRight className="h-4 w-4" />
      </button>
    );
  }

  if (repairGap?.id === "order_open_ops") {
    return renderWithFlow(
      <button
        type="button"
        disabled={runningRequestId === record.requestId}
        onClick={() => void onApplyOutcome(record.requestId, { outcome: "won", resumeAt: "", reason: `Direkt aus ${surface} als gewonnen abgeschlossen.` })}
        className="inline-flex items-center gap-2 rounded-full bg-[#0A0A0A] px-4 py-2.5 text-sm font-medium text-white transition hover:bg-black/90 disabled:cursor-not-allowed disabled:bg-black/20"
      >
        Als gewonnen schließen
        <ArrowRight className="h-4 w-4" />
      </button>
    );
  }

  if (record.communications.some((entry) => entry.direction === "inbound")) {
    const inboundTitle = record.communications.find((entry) => entry.direction === "inbound")?.title;
    return renderWithFlow(
      <a
        href={buildOutlookComposeUrl(
          record.email,
          record.displayName,
          inboundTitle ? `Re: ${inboundTitle}` : `Re: ${record.displayName || "NEONTRIP Anfrage"}`,
        )}
        target="_blank"
        rel="noreferrer"
        className="inline-flex items-center gap-2 rounded-full bg-[#0A0A0A] px-4 py-2.5 text-sm font-medium text-white transition hover:bg-black/90"
      >
        Jetzt antworten
        <ArrowRight className="h-4 w-4" />
      </a>
    );
  }

  if (record.callOps.nextCallbackAt) {
    return renderWithFlow(
      <button
        type="button"
        onClick={() => {
          if (onOpenRecord) {
            onOpenRecord("sales");
            return;
          }
          void onScheduleCallback(record.requestId, buildTomorrowAt(10), "Rückruf auf morgen verschoben.");
        }}
        disabled={runningRequestId === record.requestId}
        className="inline-flex items-center gap-2 rounded-full bg-[#0A0A0A] px-4 py-2.5 text-sm font-medium text-white transition hover:bg-black/90 disabled:cursor-not-allowed disabled:bg-black/20"
      >
        {onOpenRecord ? "Rückruf öffnen" : "Rückruf morgen"}
        <ArrowRight className="h-4 w-4" />
      </button>
    );
  }

  if (record.affectedRows.pendingFollowups > 0) {
    return renderWithFlow(
      <button
        type="button"
        disabled={runningRequestId === record.requestId}
        onClick={() => void onRescheduleFollowups(record.requestId, buildTomorrowAt(10), `Erinnerung auf morgen verschoben (${surface}).`)}
        className="inline-flex items-center gap-2 rounded-full bg-[#0A0A0A] px-4 py-2.5 text-sm font-medium text-white transition hover:bg-black/90 disabled:cursor-not-allowed disabled:bg-black/20"
      >
        Erinnerung auf morgen
        <ArrowRight className="h-4 w-4" />
      </button>
    );
  }

  if (record.quote?.viewedAt && !record.order && record.orderDiagnostic.status === "unlinked") {
    return renderWithFlow(
      <button
        type="button"
        disabled={runningRequestId === record.requestId}
        onClick={() => void onStartSalesRecovery(record.requestId, `Angebot wurde angesehen, Kaufstatus telefonisch klären (${surface}).`)}
        className="inline-flex items-center gap-2 rounded-full bg-[#0A0A0A] px-4 py-2.5 text-sm font-medium text-white transition hover:bg-black/90 disabled:cursor-not-allowed disabled:bg-black/20"
      >
        Rückgewinnung starten
        <ArrowRight className="h-4 w-4" />
      </button>
    );
  }

  if (hasCommercialDeskOpportunity(record) && onOpenCommercialDesk) {
    return renderWithFlow(
      <button
        type="button"
        onClick={onOpenCommercialDesk}
        className="inline-flex items-center gap-2 rounded-full bg-[#0A0A0A] px-4 py-2.5 text-sm font-medium text-white transition hover:bg-black/90"
      >
        Abschlussspur öffnen
        <ArrowRight className="h-4 w-4" />
      </button>
    );
  }

  if (hasContactClusterOpportunity(record) && onOpenContactPortfolio) {
    return renderWithFlow(
      <button
        type="button"
        onClick={onOpenContactPortfolio}
        className="inline-flex items-center gap-2 rounded-full bg-[#0A0A0A] px-4 py-2.5 text-sm font-medium text-white transition hover:bg-black/90"
      >
        Kontaktdossier öffnen
        <ArrowRight className="h-4 w-4" />
      </button>
    );
  }

  return renderWithFlow(null);
}

function buildOperatorRadar(records: CustomerSearchResult[]): OperatorFocusItem[] {
  const inboundReplies = records.filter((record) => record.communications.some((entry) => entry.direction === "inbound"));
  const specialCases = records.filter((record) => hasOpenSpecialCase(record));
  const specialCaseMeta = getSpecialCaseTrackMeta(specialCases);
  const repairs = records.filter((record) => Boolean(getPrimaryRepairGap(record)));
  const activeFlows = records.filter((record) => record.caseFlow.status === "active");
  const staleFlows = activeFlows.filter((record) => isActiveFlowStale(record));
  const callbacks = records.filter((record) => Boolean(record.callOps.nextCallbackAt));
  const viewedWithoutOrder = records.filter((record) => isViewedWithoutOrder(record));
  const commercial = records.filter((record) => hasCommercialDeskNonRecoveryOpportunity(record));
  const contactClusters = records.filter((record) => hasContactClusterOpportunity(record));

  return [
    {
      key: "replies",
      label: "Antworten bei mir",
      detail: "Hier hat der Kontakt schon reagiert. Das ist der schnellste Hebel für echte Bewegung.",
      count: inboundReplies.length,
      records: inboundReplies,
      tone: "rose" as const,
    },
    {
      key: "callbacks",
      label: "Meine Rückrufe",
      detail: "Fälle mit offenem Rückruf oder verschobenem Gespräch.",
      count: callbacks.length,
      records: callbacks,
      tone: "sky" as const,
    },
    {
      key: "special_cases",
      label: specialCaseMeta.title,
      detail: specialCases.length
        ? `${specialCaseMeta.detail} Diese Fälle dürfen im Tagesrauschen nicht verschwinden.`
        : "Ungelöste Problemfälle mit klarer Zuständigkeit und Fälligkeit.",
      count: specialCases.length,
      records: specialCases,
      tone: "amber" as const,
    },
    {
      key: "repairs",
      label: "Meine Reparaturen",
      detail: "Systemfehler, die sich in der Kommandozentrale beheben lassen und weitere Systeme blockieren können.",
      count: repairs.length,
      records: repairs,
      tone: "emerald" as const,
    },
    {
      key: "flows",
      label: "Meine laufenden Abläufe",
      detail: staleFlows.length
        ? `${staleFlows.length} laufende Abläufe sind veraltet und sollten vor neuer Arbeit reaktiviert werden.`
        : "Hier laufen bereits begonnene Abläufe. Diese Fälle sollten fortgesetzt statt neu gestartet werden.",
      count: activeFlows.length,
      records: activeFlows,
      tone: "sky" as const,
    },
    {
      key: "signals",
      label: "Rückgewinnung",
      detail: "Angebot wurde gesehen, aber es ist noch kein klar passender Auftrag vorhanden.",
      count: viewedWithoutOrder.length,
      records: viewedWithoutOrder,
      tone: "amber" as const,
    },
    {
      key: "commercial",
      label: "Abschluss-Fälle",
      detail: "Verkaufsfälle, Angebotsdaten, aktive Angebote und offene Abschlüsse mit Abschlussdruck.",
      count: commercial.length,
      records: commercial,
      tone: "amber" as const,
    },
    {
      key: "clusters",
      label: "Kontaktlage",
      detail: "Mehrere Fälle desselben Kontakts laufen parallel und sollten als Dossier statt einzeln bearbeitet werden.",
      count: contactClusters.length,
      records: contactClusters,
      tone: "sky" as const,
    },
  ];
}

function buildPersonalLanes(records: CustomerSearchResult[]): PersonalLane[] {
  const handover = records.filter((record) => record.caseCoordination.mode === "handover");
  const replies = records.filter((record) => record.communications.some((entry) => entry.direction === "inbound"));
  const specialCases = records.filter((record) => hasOpenSpecialCase(record));
  const specialCaseMeta = getSpecialCaseTrackMeta(specialCases);
  const repairs = records.filter((record) => Boolean(getPrimaryRepairGap(record)));
  const callbacks = records.filter((record) => Boolean(record.callOps.nextCallbackAt));
  const salesRecovery = records.filter((record) => isViewedWithoutOrder(record));
  const commercial = records.filter((record) => hasCommercialDeskNonRecoveryOpportunity(record));
  const activeFlows = records.filter((record) => record.caseFlow.status === "active");
  const dueFollowups = records.filter((record) => record.affectedRows.pendingFollowups > 0);
  const contactClusters = records.filter((record) => hasContactClusterOpportunity(record));

  return [
    {
      key: "handover",
      title: "Übergabe an mich",
      subtitle: "Fälle, die gezielt an dich übergeben wurden und zuerst Einordnung brauchen.",
      results: handover,
    },
    {
      key: "recent_replies",
      title: "Antworten bei mir",
      subtitle: "Kontakte haben schon reagiert. Das ist deine schnellste Reaktionsspur.",
      results: replies,
    },
    {
      key: "special_cases",
      title: specialCaseMeta.title,
      subtitle: `${specialCaseMeta.detail} Diese offenen Problemfälle brauchen klare Nachverfolgung.`,
      results: specialCases,
    },
    {
      key: "repairs",
      title: "Meine Reparaturen",
      subtitle: "Reparierbare Systemfehler in deinen Fällen, bevor sie weitere Systeme oder Abschlüsse verfälschen.",
      results: repairs,
    },
    {
      key: "callbacks",
      title: "Meine Rückrufe",
      subtitle: "Offene Rückrufe oder verschobene Telefontermine mit Zuständigkeitskontext.",
      results: callbacks,
    },
    {
      key: "sales_recovery",
      title: "Meine Rückgewinnung",
      subtitle: "Angebot wurde gesehen, aber es fehlt noch ein klar passender Auftrag in deinem Bestand.",
      results: salesRecovery,
    },
    {
      key: "commercial",
      title: "Meine Abschluss-Fälle",
      subtitle: "Verkaufsfälle, Angebotsdaten, aktive Entwürfe und offene Abschlüsse in deiner Spur.",
      results: commercial,
    },
    {
      key: "active_flows",
      title: "Meine laufenden Abläufe",
      subtitle: "Begonnene Abläufe, die bereits laufen und gezielt weitergeführt werden sollten, statt wieder bei null zu starten.",
      results: activeFlows,
    },
    {
      key: "contact_clusters",
      title: "Meine Kontaktlagen",
      subtitle: "Mehrere Fälle desselben Kontakts, die du besser als gemeinsames Dossier statt einzeln bearbeitest.",
      results: contactClusters,
    },
    {
      key: "due_followups",
      title: "Meine Erinnerungen",
      subtitle: "Offene Erinnerungen in deiner Spur, die jetzt Aufmerksamkeit brauchen.",
      results: dueFollowups,
    },
  ];
}

function buildOpsFeed(records: CustomerSearchResult[]) {
  return records
    .flatMap((record) =>
      record.timeline.slice(0, 8).map((entry) => {
        const sessionMeta = getOpsFeedSessionMeta({
          direction: entry.direction,
          hasSpecialCase: hasOpenSpecialCase(record),
          isHandover: record.caseCoordination.mode === "handover",
          hasRepairGap: Boolean(getPrimaryRepairGap(record)),
          hasActiveFlow: record.caseFlow.status === "active",
          hasCluster: hasContactClusterOpportunity(record),
          hasSalesRecovery: isViewedWithoutOrder(record),
          hasCommercial: hasCommercialDeskOpportunity(record),
          hasCallbackPressure: Boolean(record.callOps.nextCallbackAt),
          hasFollowupPressure: record.affectedRows.pendingFollowups > 0,
        });
        return {
          id: `${record.requestId}-${entry.id}`,
          requestId: record.requestId,
          displayName: record.displayName || record.request?.title || record.requestId,
          title: entry.title,
          description: entry.description || entry.body || null,
          occurredAt: entry.occurredAt,
          direction: entry.direction,
          source: entry.source,
          badgeLabel: sessionMeta.badgeLabel,
          preferredTab: sessionMeta.preferredTab,
          record,
        };
      }),
    )
    .sort((left, right) => new Date(right.occurredAt || 0).getTime() - new Date(left.occurredAt || 0).getTime())
    .slice(0, 12);
}

function buildActionQueues(records: CustomerSearchResult[]): ActionQueueItem[] {
  const replies = records.filter((record) => record.communications.some((entry) => entry.direction === "inbound"));
  const callbacks = records.filter(
    (record) => !replies.some((entry) => entry.requestId === record.requestId) && Boolean(record.callOps.nextCallbackAt),
  );
  const followups = records.filter(
    (record) =>
      !replies.some((entry) => entry.requestId === record.requestId) &&
      !callbacks.some((entry) => entry.requestId === record.requestId) &&
      record.affectedRows.pendingFollowups > 0,
  );
  const signals = records.filter(
    (record) =>
      !replies.some((entry) => entry.requestId === record.requestId) &&
      !callbacks.some((entry) => entry.requestId === record.requestId) &&
      !followups.some((entry) => entry.requestId === record.requestId) &&
      Boolean(record.quote?.viewedAt) &&
      !record.order &&
      record.orderDiagnostic.status === "unlinked",
  );
  const context = records.filter(
    (record) =>
      !replies.some((entry) => entry.requestId === record.requestId) &&
      !callbacks.some((entry) => entry.requestId === record.requestId) &&
      !followups.some((entry) => entry.requestId === record.requestId) &&
      !signals.some((entry) => entry.requestId === record.requestId),
  );

  return [
    {
      key: "reply",
      label: "Jetzt antworten",
      detail: "Antworten bündeln, solange der Kontakt schon in Bewegung ist.",
      tone: "rose",
      records: replies,
    },
    {
      key: "callback",
      label: "Rückrufe abarbeiten",
      detail: "Telefonische Aufgaben mit offenem Rückruffenster zuerst zusammenziehen.",
      tone: "sky",
      records: callbacks,
    },
    {
      key: "followup",
      label: "Erinnerungen steuern",
      detail: "Offene Mails und Versanddruck ohne Wechsel des Arbeitsbereichs abarbeiten.",
      tone: "amber",
      records: followups,
    },
    {
      key: "signal",
      label: "Rückgewinnung",
      detail: "Angebot gesehen, aber noch kein Auftrag. Kaufnahe Nacharbeit ohne Wechsel des Arbeitsbereichs bündeln.",
      tone: "emerald",
      records: signals,
    },
    {
      key: "context",
      label: "Lagefälle prüfen",
      detail: "Offene Fälle ohne harte Fälligkeit, aber mit relevantem Klärungsbedarf.",
      tone: "slate",
      records: context,
    },
  ];
}

function buildCommercialDesk(records: CustomerSearchResult[]): CommercialDeskItem[] {
  const viewedWithoutOrder = records.filter((record) => isViewedWithoutOrder(record));
  const orderOpenOps = records.filter((record) => hasOrderOpenOps(record));
  const crmBuilder = records.filter(
    (record) => {
      const crmQuote = record.crmQuote;
      return (
        !viewedWithoutOrder.some((entry) => entry.requestId === record.requestId) &&
        !orderOpenOps.some((entry) => entry.requestId === record.requestId) &&
        Boolean(crmQuote) &&
        ((crmQuote?.versions.length || 0) > 0 || (crmQuote?.latestVersionImages.length || 0) > 0)
      );
    },
  );
  const liveQuotes = records.filter(
    (record) =>
      !viewedWithoutOrder.some((entry) => entry.requestId === record.requestId) &&
      !orderOpenOps.some((entry) => entry.requestId === record.requestId) &&
      !crmBuilder.some((entry) => entry.requestId === record.requestId) &&
      Boolean(record.quote?.editLink || record.quote?.status || record.request?.acDealId),
  );

  return [
    {
      key: "viewed_without_order",
      label: "Gesehen, kein Auftrag",
      detail: "Angebot wurde angesehen, aber es ist noch kein Auftrag vorhanden. Das sind die Fälle nah am Abschluss.",
      tone: "amber",
      records: viewedWithoutOrder,
    },
    {
      key: "order_open_ops",
      label: "Auftrag vorhanden, Abschluss fehlt",
      detail: "Ein Auftrag ist vorhanden, aber der Fall ist noch nicht als gewonnen abgeschlossen.",
      tone: "emerald",
      records: orderOpenOps,
    },
    {
      key: "crm_builder",
      label: "Angebotsdaten aktiv",
      detail: "Hier liegt bereits Angebots-, Versions- oder Bildlage vor. Gut für Angebots- und Dossierarbeit.",
      tone: "violet",
      records: crmBuilder,
    },
    {
      key: "live_quotes",
      label: "Aktive Angebote & Verkaufsfälle",
      detail: "Offene Verkaufs- oder Angebotsfälle mit Entwurfs- oder Angebotsdaten, die jetzt weitergeführt werden können.",
      tone: "sky",
      records: liveQuotes,
    },
  ];
}

function hasCommercialDeskOpportunity(record: CustomerSearchResult) {
  return (
    isViewedWithoutOrder(record) ||
    hasOrderOpenOps(record) ||
    Boolean(record.crmQuote && ((record.crmQuote.versions.length || 0) > 0 || (record.crmQuote.latestVersionImages.length || 0) > 0)) ||
    Boolean(record.quote?.editLink || record.quote?.status || record.request?.acDealId)
  );
}

function hasCommercialDeskNonRecoveryOpportunity(record: CustomerSearchResult) {
  return hasCommercialDeskOpportunity(record) && getCommercialDeskSummary(record).key !== "viewed_without_order";
}

function getCommercialDeskSummary(record: CustomerSearchResult) {
  if (isViewedWithoutOrder(record)) {
    return {
      key: "viewed_without_order" as const,
      label: "Rückgewinnung",
      detail: record.quote?.viewedAt ? `Angebot gesehen ${formatDate(record.quote.viewedAt)}` : "Angebot gesehen, Auftrag fehlt.",
    };
  }
  if (hasOrderOpenOps(record)) {
    return {
      key: "order_open_ops" as const,
      label: "Abschluss noch offen",
      detail: record.order?.orderNumber || "Auftrag vorhanden, Fall noch in Arbeit.",
    };
  }
  if (record.crmQuote && ((record.crmQuote.versions.length || 0) > 0 || (record.crmQuote.latestVersionImages.length || 0) > 0)) {
    return {
      key: "crm_builder" as const,
      label: "Angebot aktiv",
      detail:
        record.crmQuote.quoteNumber || record.crmQuote.projectNumber || record.crmQuote.status || "Angebots- oder Bilddaten vorhanden.",
    };
  }
  return {
    key: "live_quotes" as const,
    label: "Aktive Angebote",
    detail: record.quote?.status || (record.request?.acDealId ? `Verkaufsfall ${record.request.acDealId}` : "Verkaufs- oder Angebotsdaten aktiv."),
  };
}

function getCommercialPriority(record: CustomerSearchResult) {
  if (!hasCommercialDeskOpportunity(record)) return 0;
  const summary = getCommercialDeskSummary(record);
  if (summary.key === "crm_builder") return 2;
  if (summary.key === "live_quotes") return 1;
  return 0;
}

function getCommercialSessionPresentation(
  record: CustomerSearchResult,
  scope: "global" | "operator",
  operatorName = "",
) {
  const summary = getCommercialDeskSummary(record);
  const sessionMeta = getCommercialDeskSessionMeta(summary.key);
  const isSignalSession = sessionMeta.badgeLabel === "Kaufinteresse";
  const trimmedOperator = operatorName.trim();
  const operatorSuffix = trimmedOperator ? ` • ${trimmedOperator}` : "";

  return {
    summary,
    ...sessionMeta,
    label: isSignalSession
      ? scope === "operator"
        ? `Mein Kaufinteresse${operatorSuffix}`
        : "Kaufinteresse"
      : scope === "operator"
        ? `Meine Abschluss-Fälle${operatorSuffix}`
        : "Abschlussspur",
    launcherLabel: isSignalSession
      ? scope === "operator"
        ? "Mein Kaufinteresse"
        : "Kaufinteresse öffnen"
      : scope === "operator"
        ? "Meine Abschlussspur"
        : "Abschlussspur starten",
    launcherDetail: isSignalSession
      ? scope === "operator"
        ? trimmedOperator
          ? `Öffnet die persönliche Kaufinteressenspur für ${trimmedOperator}.`
          : "Verfügbar, sobald eine zuständige Person gesetzt ist."
        : "Öffnet die vorrangigen Fälle mit Kaufinteresse ohne Auftrag als Rückgewinnung."
      : scope === "operator"
        ? trimmedOperator
          ? `Öffnet die persönliche Abschlussspur für ${trimmedOperator}.`
          : "Verfügbar, sobald eine zuständige Person gesetzt ist."
        : "Öffnet die gesammelte Verkaufs-, Angebots- und Bildspur mit dem führenden Fall.",
  };
}

function getCommercialBriefPresentation(
  record: CustomerSearchResult | null,
  scope: "global" | "operator",
  operatorName = "",
) {
  if (!record) {
    return {
      title: scope === "operator" ? `NEONTRIP Abschluss • ${operatorName.trim()}` : "NEONTRIP Abschluss",
      copyLabel: scope === "operator" ? "Meinen Abschluss kopieren" : "Abschluss kopieren",
      buttonLabel: scope === "operator" ? "Mein Abschluss" : "Abschluss kopieren",
      successMessage: scope === "operator" ? "Mein Abschluss kopiert." : "Abschluss kopiert.",
    };
  }

  const session = getCommercialSessionPresentation(record, scope, operatorName);
  const isSignalSession = session.badgeLabel === "Kaufinteresse";
  const trimmedOperator = operatorName.trim();

  return {
    title: isSignalSession
      ? scope === "operator"
        ? `NEONTRIP Kaufinteresse • ${trimmedOperator}`
        : "NEONTRIP Kaufinteresse"
      : scope === "operator"
        ? `NEONTRIP Abschluss • ${trimmedOperator}`
        : "NEONTRIP Abschluss",
    copyLabel: isSignalSession
      ? scope === "operator"
        ? "Mein Kaufinteresse kopieren"
        : "Kaufinteresse kopieren"
      : scope === "operator"
        ? "Meinen Abschluss kopieren"
        : "Abschluss kopieren",
    buttonLabel: isSignalSession
      ? scope === "operator"
        ? "Mein Kaufinteresse kopieren"
        : "Kaufinteresse kopieren"
      : scope === "operator"
        ? "Meinen Abschluss kopieren"
        : "Abschluss kopieren",
    successMessage: isSignalSession
      ? scope === "operator"
        ? "Mein Kaufinteresse kopiert."
        : "Kaufinteresse kopiert."
      : scope === "operator"
        ? "Mein Abschluss kopiert."
        : "Abschluss kopiert.",
  };
}

function buildCommercialSessionOptions(
  record: CustomerSearchResult,
  deskItems?: CommercialDeskItem[],
): RequestIdSessionOpenOptions {
  const session = getCommercialSessionPresentation(record, "global");
  const matchingItem =
    deskItems?.find(
      (item) => item.key === session.summary.key && item.records.some((entry) => entry.requestId === record.requestId),
    ) || deskItems?.find((item) => item.records.some((entry) => entry.requestId === record.requestId));
  const sessionRecords = matchingItem?.records.length ? matchingItem.records : [record];
  const preferredTab = session.preferredTab ?? getSessionPreferredTab(session.badgeLabel) ?? inferPreferredTab(record);

  return buildRecordSessionOpenOptions({
    records: sessionRecords,
    source: "workboard",
    badgeLabel: session.badgeLabel,
    label: matchingItem ? `${session.label} • ${matchingItem.label}` : session.label,
    preferredTab,
  });
}

function getBatchRiskWarnings(records: CustomerSearchResult[]) {
  const blocked = records.filter(
    (record) => record.opsState.status === "do_not_contact" || record.callOps.contactabilityStatus === "blocked",
  );
  const vacation = records.filter((record) => record.opsState.status === "vacation");
  const missingContext = records.filter(
    (record) => !record.trello || (!record.trello.mockups.length && !record.trello.referenceImage),
  );
  const missingPhone = records.filter((record) => !record.phone?.trim());

  return [
    blocked.length
      ? {
          key: "blocked",
          tone: "border-rose-200 bg-rose-50 text-rose-900",
          text: `${blocked.length} Fall${blocked.length === 1 ? "" : "e"} mit Kontaktstopp oder gesperrter Erreichbarkeit.`,
        }
      : null,
    vacation.length
      ? {
          key: "vacation",
          tone: "border-amber-200 bg-amber-50 text-amber-900",
          text: `${vacation.length} Fall${vacation.length === 1 ? "" : "e"} stehen auf Urlaub / später.`,
        }
      : null,
    missingContext.length
      ? {
          key: "context",
          tone: "border-slate-200 bg-slate-50 text-slate-900",
          text: `${missingContext.length} Fall${missingContext.length === 1 ? "" : "e"} ohne vollständige Karten-/Designlage.`,
        }
      : null,
    missingPhone.length && records.some((record) => Boolean(record.callOps.nextCallbackAt) || (record.quote?.viewedAt && !record.order))
      ? {
          key: "phone",
          tone: "border-sky-200 bg-sky-50 text-sky-900",
          text: `${missingPhone.length} Fall${missingPhone.length === 1 ? "" : "e"} ohne passende Telefonnummer für telefonische Nacharbeit.`,
        }
      : null,
  ].filter(Boolean) as Array<{ key: string; tone: string; text: string }>;
}

function isBatchEligible(record: CustomerSearchResult) {
  return record.opsState.status !== "do_not_contact" && record.callOps.contactabilityStatus !== "blocked" && record.opsState.status !== "vacation";
}

function getBatchSkipReason(record: CustomerSearchResult) {
  if (record.opsState.status === "do_not_contact" || record.callOps.contactabilityStatus === "blocked") {
    return "Kontaktstopp oder gesperrte Erreichbarkeit";
  }
  if (record.opsState.status === "vacation") {
    return "Fall ist auf Urlaub / später gesetzt";
  }
  return "Dieser Fall ist für diese Sammelaktion nicht freigegeben";
}

function inferPreferredTab(record: CustomerSearchResult): RecordDetailTab {
  const hasLatestInbound = record.communications.some((entry) => entry.direction === "inbound");
  const hasCallbackPressure = Boolean(record.callOps.nextCallbackAt);
  const hasViewedWithoutOrder = isViewedWithoutOrder(record);
  const hasCommercialPressure = hasCommercialDeskOpportunity(record);
  const missingDesignContext = !record.trello || (!record.trello.mockups.length && !record.trello.referenceImage);
  const hasFollowupPressure = record.affectedRows.pendingFollowups > 0;
  const hasHardOpsState = record.opsState.status === "do_not_contact" || record.opsState.status === "vacation";

  if (hasLatestInbound) return "communication";
  if (hasCallbackPressure || hasViewedWithoutOrder) return "sales";
  if (hasCommercialPressure) return "deal";
  if (missingDesignContext) return "trello";
  if (hasHardOpsState || hasFollowupPressure) return "history";
  return "contact";
}

function hasOrderOpenOps(record: CustomerSearchResult) {
  if (!record.order) return false;
  if (record.opsState.status === "won" || record.opsState.status === "lost" || record.opsState.status === "do_not_contact") {
    return false;
  }
  return record.affectedRows.pendingFollowups > 0 || Boolean(record.callOps.nextCallbackAt) || record.opsState.status !== "active";
}

function getSystemGapItems(record: CustomerSearchResult): SystemGapItem[] {
  const gaps: SystemGapItem[] = [];
  const downstreamEmails = record.downstreamPreview.followupEmails.filter(Boolean);
  const emailMismatch = downstreamEmails.some((email) => email.toLowerCase() !== record.email.toLowerCase());

  if (emailMismatch || downstreamEmails.length > 1) {
    gaps.push({
      id: "email_drift",
      tone: "rose",
      title: "E-Mail weicht in weiteren Systemen ab",
      detail: downstreamEmails.length
        ? `Im Fall steht ${record.email}, in den weiteren Systemen aber: ${downstreamEmails.join(", ")}`
        : "Im Kontakt ist eine E-Mail vorhanden, aber die weiteren Systeme zeigen keinen klaren Empfänger.",
      tab: "contact",
      actionLabel: "Abgleich beheben",
    });
  }

  if (record.opsState.status === "do_not_contact" && record.affectedRows.pendingFollowups > 0) {
    gaps.push({
      id: "blocked_followups",
      tone: "rose",
      title: "Kontaktstopp bei noch offenen Erinnerungen",
      detail: `${record.affectedRows.pendingFollowups} Erinnerung${record.affectedRows.pendingFollowups === 1 ? "" : "en"} sind noch offen, obwohl der Fall auf Kontaktstopp steht.`,
      tab: "history",
      actionLabel: "Erinnerungen stoppen",
    });
  }

  if ((!record.trello || (!record.trello.mockups.length && !record.trello.referenceImage)) && record.request?.trelloCardUrl) {
    gaps.push({
      id: "trello_context_thin",
      tone: "amber",
      title: "Karten angelegt, aber kaum Medienlage",
      detail: "Es gibt bereits Karten, aber kein klares Entwurfsbild oder Referenzbild in der Medienlage.",
      tab: "trello",
      actionLabel: "Karten prüfen",
    });
  }

  if (isViewedWithoutOrder(record)) {
    const viewedAt = record.quote?.viewedAt;
    gaps.push({
      id: "viewed_without_order",
      tone: "amber",
      title: "Angebot gesehen, Auftrag fehlt",
      detail: viewedAt
        ? `Das Angebot wurde am ${formatDate(viewedAt)} angesehen, aber es gibt noch keinen passenden Auftrag.`
        : "Das Angebot wurde gesehen, aber es gibt noch keinen passenden Auftrag.",
      tab: "sales",
      actionLabel: record.phone?.trim() ? "Rückgewinnung starten" : "Verkaufsdaten öffnen",
    });
  }

  if (hasOrderOpenOps(record)) {
    gaps.push({
      id: "order_open_ops",
      tone: "amber",
      title: "Auftrag vorhanden, Fall noch in Arbeit",
      detail: record.callOps.nextCallbackAt
        ? `Auftrag ist schon da, aber es steht noch ein Rückruf für ${formatDate(record.callOps.nextCallbackAt)} offen.`
        : record.affectedRows.pendingFollowups > 0
          ? `Auftrag ist schon da, aber ${record.affectedRows.pendingFollowups} Erinnerung${record.affectedRows.pendingFollowups === 1 ? "" : "en"} laufen noch.`
          : "Auftrag ist schon da, aber der Fall ist noch nicht als gewonnen abgeschlossen.",
      tab: "history",
      actionLabel: "Als gewonnen schließen",
    });
  }

  if (record.callOps.nextCallbackAt && !record.phone?.trim()) {
    gaps.push({
      id: "callback_no_phone",
      tone: "slate",
      title: "Rückruf geplant, aber keine Telefonnummer",
      detail: `Rückruf ist für ${formatDate(record.callOps.nextCallbackAt)} geplant, jedoch fehlt im Fall eine nutzbare Nummer.`,
      tab: "contact",
      actionLabel: "Telefonnummer ergänzen",
    });
  }

  if (record.communications.length > 0 && !record.communications.some((entry) => entry.direction === "inbound") && record.affectedRows.pendingFollowups > 0) {
    gaps.push({
      id: "outbound_only_followup",
      tone: "slate",
      title: "Nur Ausgangsspuren bei offener Erinnerung",
      detail: "Es gibt Kommunikationsereignisse, aber keine eingehende Spur für den offenen Folgeprozess.",
      tab: "communication",
      actionLabel: "Kommunikation prüfen",
    });
  }

  return gaps;
}

function getSyncHealthItems(record: CustomerSearchResult): SyncHealthItem[] {
  const downstreamEmails = record.downstreamPreview.followupEmails.filter(Boolean);
  const emailMismatch = downstreamEmails.some((email) => email.toLowerCase() !== record.email.toLowerCase());
  const hasDesignContext = Boolean(record.trello && (record.trello.mockups.length || record.trello.referenceImage));
  const viewedWithoutOrder = isViewedWithoutOrder(record);
  const orderOpenOps = hasOrderOpenOps(record);
  const trelloCardsCount = record.trello?.cards.length || 0;

  const items: SyncHealthItem[] = [
    {
      key: "master",
      label: "Führende Kontaktdaten",
      status: record.email && record.displayName ? "ok" : "watch",
      value: record.email ? "Kontaktdaten vollständig" : "Kontakt unvollständig",
      detail: record.email
        ? record.phone?.trim()
          ? "Der führende Kontakt ist vollständig und grundsätzlich einsatzbereit."
          : "E-Mail steht, aber eine passende Telefonnummer fehlt noch im führenden Kontakt."
        : "Im führenden Kontakt fehlen wichtige Daten für die weitere Bearbeitung.",
      tab: "contact",
      actionLabel: "Kontakt prüfen",
      action: "open",
    },
    emailMismatch || downstreamEmails.length > 1
      ? {
          key: "downstream",
          label: "Weitere Systeme",
          status: "repair",
          value: "Abgleich weicht ab",
          detail: downstreamEmails.length
            ? `Im führenden Kontakt steht ${record.email}, die weiteren Systeme nutzen aber ${downstreamEmails.join(", ")}.`
            : "Der Abgleich der weiteren Systeme passt noch nicht zu den Kontaktdaten.",
          tab: "contact",
          actionLabel: "Abgleich beheben",
          action: "repair_downstream_sync",
        }
      : record.opsState.status === "do_not_contact" && record.affectedRows.pendingFollowups > 0
        ? {
            key: "downstream",
            label: "Weitere Systeme",
            status: "repair",
            value: "Kontaktstopp widerspricht",
            detail: `${record.affectedRows.pendingFollowups} offene Erinnerung${record.affectedRows.pendingFollowups === 1 ? "" : "en"} laufen noch gegen einen gestoppten Kontakt.`,
            tab: "history",
            actionLabel: "Erinnerungen stoppen",
            action: "pause_followups",
          }
        : {
            key: "downstream",
            label: "Weitere Systeme",
            status: record.affectedRows.pendingFollowups > 0 ? "watch" : "ok",
            value: record.affectedRows.pendingFollowups > 0 ? `${record.affectedRows.pendingFollowups} Erinnerung${record.affectedRows.pendingFollowups === 1 ? "" : "en"} ausstehend` : "Abgleich passt",
            detail: record.affectedRows.pendingFollowups > 0
              ? `Nächste Erinnerung: ${formatDate(record.affectedRows.nextPendingFollowupAt)}`
              : "Erinnerungs-, Plan- und Dokumentenlage passen zum führenden Kontakt.",
            tab: "history",
            actionLabel: "Verlauf prüfen",
            action: "open",
          },
    record.request?.trelloCardUrl && !record.trello
      ? {
          key: "trello",
          label: "Karten- und Medienlage",
          status: "repair",
          value: "Keine Kartenlage",
          detail: "Es gibt bereits Karten, aber in der Kommandozentrale ist noch keine klare Kartenlage.",
          tab: "trello",
          actionLabel: "Karten prüfen",
          action: "open",
        }
      : !hasDesignContext && trelloCardsCount > 0
        ? {
            key: "trello",
          label: "Karten- und Medienlage",
            status: "watch",
            value: `${trelloCardsCount}/3 Kartenlisten ohne Medienlage`,
            detail: "Karten sind schon da, aber Entwurfsbild oder Referenzbild fehlen in dieser Lage.",
            tab: "trello",
            actionLabel: "Design prüfen",
            action: "open",
          }
        : {
            key: "trello",
          label: "Karten- und Medienlage",
            status: hasDesignContext ? "ok" : "watch",
            value: hasDesignContext ? `${record.trello?.mockups.length || 0} Entwurfsbilder vorhanden` : "Medienlage lückenhaft",
            detail: hasDesignContext
              ? `${trelloCardsCount}/3 Kartenlisten liegen vor, Referenzbild und Medienlage sind gut nutzbar.`
              : "Noch keine klare Medienlage aus Karten oder Angebotsdaten vorhanden.",
            tab: "trello",
            actionLabel: "Karten & Medien",
            action: "open",
          },
    viewedWithoutOrder && record.phone?.trim()
      ? {
          key: "sales",
          label: "Verkaufslage",
          status: "repair",
          value: "Rückgewinnung nötig",
          detail: `Angebot wurde am ${formatDate(record.quote?.viewedAt || null)} angesehen, aber es fehlt noch ein klar passender Auftrag.`,
          tab: "sales",
          actionLabel: "Rückgewinnung starten",
          action: "start_sales_recovery",
        }
      : orderOpenOps
        ? {
            key: "sales",
            label: "Verkaufslage",
            status: "repair",
            value: "Auftrag vorhanden, Fall noch in Arbeit",
            detail: "Bestellung ist schon vorhanden, aber Erinnerungen, Rückruf oder ein offener Fallstand laufen noch.",
            tab: "history",
            actionLabel: "Als gewonnen schließen",
            action: "mark_won",
          }
        : {
            key: "sales",
            label: "Verkaufslage",
            status: record.order ? "ok" : viewedWithoutOrder ? "watch" : "watch",
            value: record.order ? "Auftrag vorhanden" : viewedWithoutOrder ? "Angebot noch offen" : "Kein Auftrag",
            detail: record.order
              ? `${orderSourceLabel(record.order.source)} • ${formatMoney(record.order.orderValue, record.order.currency || "EUR")}`
              : record.orderDiagnostic.summary,
            tab: "sales",
            actionLabel: "Verkaufsdaten öffnen",
            action: "open",
          },
    record.callOps.nextCallbackAt && !record.phone?.trim()
      ? {
          key: "calls",
          label: "Erreichbarkeit",
          status: "repair",
          value: "Rückruf ohne Telefonnummer",
          detail: `Es existiert ein Rückruf für ${formatDate(record.callOps.nextCallbackAt)}, aber im Fall fehlt eine passende Telefonnummer.`,
          tab: "contact",
          actionLabel: "Telefonnummer ergänzen",
          action: "open",
        }
      : {
          key: "calls",
          label: "Erreichbarkeit",
          status: record.callOps.contactabilityStatus === "blocked" ? "watch" : record.callOps.totalCallCount > 0 ? "ok" : "watch",
          value:
            record.callOps.contactabilityStatus === "blocked"
              ? "Kontakt gesperrt"
              : record.callOps.totalCallCount > 0
                ? `${record.callOps.totalCallCount} Anrufeintrag${record.callOps.totalCallCount === 1 ? "" : "e"}`
                : "Keine Anrufe erfasst",
          detail:
            record.callOps.contactabilityStatus === "blocked"
              ? "Erreichbarkeit ist eingeschränkt; Folgearbeit darf nur gezielt erfolgen."
              : record.callOps.latestLoggedCallSummary || "Noch keine klare Anrufnotiz oder Rückrufzusammenfassung.",
          tab: "sales",
          actionLabel: "Anrufe ansehen",
          action: "open",
        },
  ];

  return items;
}

function buildSystemGapQueue(records: CustomerSearchResult[]): SystemGapQueueItem[] {
  const buckets = new Map<SystemGapItem["id"], SystemGapQueueItem>();

  for (const record of records) {
    for (const gap of getSystemGapItems(record)) {
      const existing = buckets.get(gap.id);
      if (existing) {
        existing.records.push(record);
        if (!existing.lead) existing.lead = record;
        continue;
      }
      buckets.set(gap.id, {
        key: gap.id,
        title: gap.title,
        detail: gap.detail,
        tone: gap.tone,
        records: [record],
        lead: record,
        actionLabel: gap.actionLabel,
        preferredTab: gap.tab,
      });
    }
  }

  return Array.from(buckets.values()).sort((left, right) => right.records.length - left.records.length);
}

function buildRepairQueue(records: CustomerSearchResult[]): SystemGapQueueItem[] {
  const allowed = new Set<SystemGapItem["id"]>([
    "email_drift",
    "blocked_followups",
    "viewed_without_order",
    "order_open_ops",
  ]);
  const base = buildSystemGapQueue(records).filter((item) => allowed.has(item.key));
  const priority: Record<SystemGapItem["id"], number> = {
    email_drift: 0,
    blocked_followups: 1,
    viewed_without_order: 2,
    order_open_ops: 3,
    trello_context_thin: 4,
    callback_no_phone: 5,
    outbound_only_followup: 6,
  };

  return base
    .map((item) => ({
      ...item,
      title:
        item.key === "email_drift"
          ? "Abgleich beheben"
          : item.key === "blocked_followups"
            ? "Kontaktstopp vollständig durchziehen"
            : item.key === "viewed_without_order"
              ? "Rückgewinnung starten"
              : "Gewonnene Fälle schließen",
      detail:
        item.key === "email_drift"
          ? "Führender Kontakt und weitere Systeme weichen voneinander ab. Diese Spur zieht die betroffenen Daten wieder auf den führenden Stand."
          : item.key === "blocked_followups"
            ? "Kontaktstopp ist schon gesetzt, aber Abläufe laufen noch. Diese Spur räumt solche Widersprüche gesammelt weg."
            : item.key === "viewed_without_order"
              ? "Angebot wurde gesehen, aber noch kein klar passender Auftrag ist vorhanden. Diese Spur bündelt Weiterarbeit nah am Abschluss."
              : "Ein Auftrag ist schon vorhanden, aber der Fall ist noch nicht als gewonnen markiert.",
    }))
    .sort((left, right) => {
      const byPriority = priority[left.key] - priority[right.key];
      if (byPriority !== 0) return byPriority;
      return right.records.length - left.records.length;
    });
}

function getRepairGapLabel(gapId: NonNullable<ReturnType<typeof getPrimaryRepairGap>>["id"]) {
  switch (gapId) {
    case "email_drift":
      return "Abgleich";
    case "blocked_followups":
      return "Stopp";
    case "viewed_without_order":
      return "Rückgewinnung";
    case "order_open_ops":
      return "Abschluss";
    default:
      return "Reparatur";
  }
}

function buildRepairOwnershipGroups(records: CustomerSearchResult[]): RepairOwnershipGroup[] {
  const assignedGroups: RepairOwnershipGroup[] = OPERATOR_PRESETS.map((name) => {
    const normalized = normalizePersonName(name);
    const repairs = sortRecordsByOpsPriority(
      records.filter(
        (record) =>
          normalizePersonName(record.caseCoordination.ownerName) === normalized &&
          Boolean(getPrimaryRepairGap(record)),
      ),
    );

    return {
      key: name,
      label: name,
      repairs,
    };
  }).filter((group) => group.repairs.length);

  const unassignedRepairs = sortRecordsByOpsPriority(
    records.filter((record) => {
      const gap = getPrimaryRepairGap(record);
      if (!gap) return false;
      const owner = normalizePersonName(record.caseCoordination.ownerName);
      return !owner || !OPERATOR_PRESETS.some((preset) => normalizePersonName(preset) === owner);
    }),
  );

  if (unassignedRepairs.length) {
    assignedGroups.push({
      key: "unassigned",
      label: "Unzugewiesen",
      repairs: unassignedRepairs,
    });
  }

  return assignedGroups;
}

function buildContactClusterOwnershipGroups(records: CustomerSearchResult[]): ContactClusterOwnershipGroup[] {
  const assignedGroups: ContactClusterOwnershipGroup[] = OPERATOR_PRESETS.map((name) => {
    const normalized = normalizePersonName(name);
    const clusters = sortRecordsByOpsPriority(
      records.filter(
        (record) =>
          normalizePersonName(record.caseCoordination.ownerName) === normalized && hasContactClusterOpportunity(record),
      ),
    );

    return {
      key: name,
      label: name,
      clusters,
    };
  }).filter((group) => group.clusters.length);

  const unassignedClusters = sortRecordsByOpsPriority(
    records.filter((record) => {
      if (!hasContactClusterOpportunity(record)) {
        return false;
      }
      const owner = normalizePersonName(record.caseCoordination.ownerName);
      return !owner || !OPERATOR_PRESETS.some((preset) => normalizePersonName(preset) === owner);
    }),
  );

  if (unassignedClusters.length) {
    assignedGroups.push({
      key: "unassigned",
      label: "Unzugewiesen",
      clusters: unassignedClusters,
    });
  }

  return assignedGroups;
}

function buildCommercialOwnershipGroups(records: CustomerSearchResult[]): CommercialOwnershipGroup[] {
  const assignedGroups: CommercialOwnershipGroup[] = OPERATOR_PRESETS.map((name) => {
    const normalized = normalizePersonName(name);
    const commercial = sortRecordsByOpsPriority(
      records.filter(
        (record) =>
          normalizePersonName(record.caseCoordination.ownerName) === normalized &&
          hasCommercialDeskNonRecoveryOpportunity(record),
      ),
    );

    return {
      key: name,
      label: name,
      commercial,
    };
  }).filter((group) => group.commercial.length);

  const unassignedCommercial = sortRecordsByOpsPriority(
    records.filter((record) => {
      if (!hasCommercialDeskNonRecoveryOpportunity(record)) return false;
      const owner = normalizePersonName(record.caseCoordination.ownerName);
      return !owner || !OPERATOR_PRESETS.some((preset) => normalizePersonName(preset) === owner);
    }),
  );

  if (unassignedCommercial.length) {
    assignedGroups.push({
      key: "unassigned",
      label: "Unzugewiesen",
      commercial: unassignedCommercial,
    });
  }

  return assignedGroups;
}

function buildFlowOwnershipGroups(records: CustomerSearchResult[]): FlowOwnershipGroup[] {
  const assignedGroups: FlowOwnershipGroup[] = OPERATOR_PRESETS.map((name) => {
    const normalized = normalizePersonName(name);
    const flows = sortRecordsByOpsPriority(
      records.filter(
        (record) => normalizePersonName(record.caseCoordination.ownerName) === normalized && record.caseFlow.status === "active",
      ),
    );

    return {
      key: name,
      label: name,
      flows,
    };
  }).filter((group) => group.flows.length);

  const unassignedFlows = sortRecordsByOpsPriority(
    records.filter((record) => {
      if (record.caseFlow.status !== "active") return false;
      const owner = normalizePersonName(record.caseCoordination.ownerName);
      return !owner || !OPERATOR_PRESETS.some((preset) => normalizePersonName(preset) === owner);
    }),
  );

  if (unassignedFlows.length) {
    assignedGroups.push({
      key: "unassigned",
      label: "Unzugewiesen",
      flows: unassignedFlows,
    });
  }

  return assignedGroups;
}

function shortSectionSubtitle(section: CustomerWorkboardSection) {
  switch (section.key) {
    case "due_followups":
      return "Fällige Erinnerungen.";
    case "callbacks":
      return "Rückrufe auf einen Blick.";
    case "sales_recovery":
      return "Angebot gesehen, Auftrag fehlt.";
    case "recent_replies":
      return "Frische Antworten zuerst.";
    case "contact_stops":
      return "Kontaktstopps auf einen Blick.";
    default:
      return section.subtitle;
  }
}

function InboxCard({
  record,
  onOpen,
  onOpenPortfolio,
  onOpenCommercialDesk,
  onRescheduleFollowups,
  onScheduleCallback,
  onStartSalesRecovery,
  onApplyOutcome,
  onLogCall,
  onPauseFollowups,
  onRepairDownstreamSync,
  runningRequestId,
  simpleView = false,
}: {
  record: CustomerSearchResult;
  onOpen: () => void;
  onOpenPortfolio: () => void;
  onOpenCommercialDesk: () => void;
  onRescheduleFollowups: (requestId: string, resumeAt: string, reason: string) => Promise<void>;
  onScheduleCallback: (requestId: string, resumeAt: string, reason: string) => Promise<void>;
  onStartSalesRecovery: (requestId: string, reason: string) => Promise<void>;
  onApplyOutcome: (requestId: string, outcome: CaseOutcomeDraft) => Promise<void>;
  onLogCall: (requestId: string, call: CallLogDraft) => Promise<void>;
  onPauseFollowups: (requestId: string) => Promise<void>;
  onRepairDownstreamSync: (requestId: string) => Promise<void>;
  runningRequestId: string | null;
  simpleView?: boolean;
}) {
  const priorityTone =
    record.affectedRows.pendingFollowups > 0
      ? "border-[#fa31a2]/20 bg-[#fff7fb]"
      : "border-black/10 bg-white";

  if (simpleView) {
    return (
      <div className={`w-full rounded-2xl border p-3 text-left ${priorityTone}`}>
        <div className="flex flex-wrap items-start justify-between gap-3">
          <button type="button" onClick={onOpen} className="min-w-0 flex-1 text-left">
            <div className="text-sm font-semibold text-black">{record.displayName || record.request?.title || record.requestId}</div>
            <div className="mt-1 text-xs text-black/55">
              {record.affectedRows.nextPendingFollowupAt
                ? `Nächste Erinnerung ${formatDate(record.affectedRows.nextPendingFollowupAt)}`
                : record.request?.status || "Offen"}
            </div>
          </button>
          <div className="flex flex-wrap justify-end gap-2">
            <ActiveViewerBadge record={record} />
            <div className="rounded-full border border-black/10 bg-white px-2.5 py-1 text-[10px] uppercase tracking-[0.14em] text-black/55">
              {record.affectedRows.pendingFollowups > 0 ? `${record.affectedRows.pendingFollowups} offen` : "bereit"}
            </div>
          </div>
        </div>
        <div className="mt-3">
          <SimpleSpecialCaseFlag record={record} />
          <RecommendedPrimaryAction
            record={record}
            surface="Eingang"
            runningRequestId={runningRequestId}
            onRescheduleFollowups={onRescheduleFollowups}
            onScheduleCallback={onScheduleCallback}
            onStartSalesRecovery={onStartSalesRecovery}
            onPauseFollowups={onPauseFollowups}
            onRepairDownstreamSync={onRepairDownstreamSync}
            onApplyOutcome={onApplyOutcome}
            onOpenContactPortfolio={onOpenPortfolio}
            onOpenCommercialDesk={onOpenCommercialDesk}
            showFlowAssist
            onOpenRecord={() => onOpen()}
          />
        </div>
      </div>
    );
  }

  return (
    <div className={`w-full rounded-2xl border p-4 text-left transition hover:border-[#fa31a2]/35 hover:bg-[#fa31a2]/[0.03] ${priorityTone}`}>
      <button
        type="button"
        onClick={onOpen}
        className="w-full text-left"
      >
        <div className="flex items-start justify-between gap-4">
          <div className="min-w-0">
            <div className="text-sm font-semibold text-black">{record.displayName || record.request?.title || record.requestId}</div>
            <div className="mt-1 text-xs uppercase tracking-[0.14em] text-black/40">{record.requestId}</div>
          </div>
          <div className="flex flex-wrap justify-end gap-2">
            <ActiveViewerBadge record={record} />
            <div className="rounded-full border border-black/10 bg-white px-2.5 py-1 text-[10px] uppercase tracking-[0.14em] text-black/55">
              {record.affectedRows.pendingFollowups > 0 ? `${record.affectedRows.pendingFollowups} offen` : "frisch"}
            </div>
          </div>
        </div>
        <div className="mt-3 text-sm leading-6 text-black/60">
          {record.request?.status || "Stand ausstehend"}
          {record.request?.acDealId ? ` • Verkaufsfall ${record.request.acDealId}` : ""}
          {record.request ? ` • ${getAiSegmentLabel(record.request)}` : ""}
          {record.request?.sKategorie ? ` • ${record.request.sKategorie}` : ""}
          {record.request?.segmentStatus ? ` • KI ${getSegmentStatusLabel(record.request.segmentStatus)}` : ""}
        </div>
        <div className="mt-2 text-sm leading-6 text-black/55">
          {record.affectedRows.nextPendingFollowupAt
            ? `Nächster Versand ${formatDate(record.affectedRows.nextPendingFollowupAt)}`
            : `Zuletzt aktualisiert ${formatDate(record.request?.updatedAt || record.updatedAt)}`}
        </div>
      </button>
      <RecommendedActionInline record={record} />
      <div className="mt-3">
        <RecommendedPrimaryAction
          record={record}
          surface="Eingang"
          runningRequestId={runningRequestId}
          onRescheduleFollowups={onRescheduleFollowups}
          onScheduleCallback={onScheduleCallback}
          onStartSalesRecovery={onStartSalesRecovery}
          onPauseFollowups={onPauseFollowups}
          onRepairDownstreamSync={onRepairDownstreamSync}
          onApplyOutcome={onApplyOutcome}
          onOpenContactPortfolio={onOpenPortfolio}
          onOpenCommercialDesk={onOpenCommercialDesk}
          showFlowAssist
          onOpenRecord={() => onOpen()}
        />
      </div>
      <div className="mt-3 flex flex-wrap gap-2">
        {record.communications.some((entry) => entry.direction === "inbound") ? (
          <a
            href={buildOutlookComposeUrl(
              record.email,
              record.displayName,
              record.communications.find((entry) => entry.direction === "inbound")?.title
                ? `Re: ${record.communications.find((entry) => entry.direction === "inbound")?.title}`
                : `Re: ${record.displayName || "NEONTRIP Anfrage"}`,
            )}
            target="_blank"
            rel="noreferrer"
            onClick={(event) => event.stopPropagation()}
            className="rounded-full border border-black/10 bg-white px-3 py-2 text-xs font-medium text-black/65 transition hover:border-[#fa31a2] hover:text-black"
          >
            Antworten
          </a>
        ) : null}
        {record.callOps.nextCallbackAt ? (
          <button
            type="button"
            disabled={runningRequestId === record.requestId}
            onClick={(event) => {
              event.stopPropagation();
              void onScheduleCallback(record.requestId, buildTomorrowAt(10), "Rückruf auf morgen verschoben.");
            }}
            className="rounded-full border border-black/10 bg-white px-3 py-2 text-xs font-medium text-black/65 transition hover:border-[#fa31a2] hover:text-black disabled:cursor-not-allowed disabled:opacity-50"
          >
            Rückruf morgen
          </button>
        ) : null}
        <button
          type="button"
          disabled={runningRequestId === record.requestId}
          onClick={(event) => {
            event.stopPropagation();
            void onLogCall(record.requestId, buildQuickCallDraft("voicemail", "Eingang"));
          }}
          className="rounded-full border border-black/10 bg-white px-3 py-2 text-xs font-medium text-black/65 transition hover:border-[#fa31a2] hover:text-black disabled:cursor-not-allowed disabled:opacity-50"
        >
          Anrufbeantworter
        </button>
        <button
          type="button"
          disabled={runningRequestId === record.requestId}
          onClick={(event) => {
            event.stopPropagation();
            void onLogCall(record.requestId, buildQuickCallDraft("reached", "Eingang"));
          }}
          className="rounded-full border border-black/10 bg-white px-3 py-2 text-xs font-medium text-black/65 transition hover:border-[#fa31a2] hover:text-black disabled:cursor-not-allowed disabled:opacity-50"
        >
          Erreicht
        </button>
        <button
          type="button"
          disabled={runningRequestId === record.requestId}
          onClick={(event) => {
            event.stopPropagation();
            void onLogCall(record.requestId, buildQuickCallDraft("vacation", "Eingang"));
          }}
          className="rounded-full border border-amber-200 bg-amber-50 px-3 py-2 text-xs font-medium text-amber-800 transition hover:border-amber-300 hover:bg-amber-100 disabled:cursor-not-allowed disabled:opacity-50"
        >
          Urlaub
        </button>
        {record.affectedRows.pendingFollowups > 0 ? (
          <button
            type="button"
            disabled={runningRequestId === record.requestId}
            onClick={(event) => {
              event.stopPropagation();
              void onRescheduleFollowups(record.requestId, buildTomorrowAt(10), "Erinnerung auf morgen verschoben.");
            }}
            className="rounded-full border border-black/10 bg-white px-3 py-2 text-xs font-medium text-black/65 transition hover:border-[#fa31a2] hover:text-black disabled:cursor-not-allowed disabled:opacity-50"
          >
            Erinnerung auf morgen
          </button>
        ) : null}
        <button
          type="button"
          disabled={runningRequestId === record.requestId}
          onClick={(event) => {
            event.stopPropagation();
            void onApplyOutcome(record.requestId, { outcome: "won", resumeAt: "", reason: "Direkt aus dem Eingang als gewonnen markiert." });
          }}
          className="rounded-full border border-emerald-200 bg-emerald-50 px-3 py-2 text-xs font-medium text-emerald-800 transition hover:border-emerald-300 hover:bg-emerald-100 disabled:cursor-not-allowed disabled:opacity-50"
        >
          Gewonnen
        </button>
        <button
          type="button"
          disabled={runningRequestId === record.requestId}
          onClick={(event) => {
            event.stopPropagation();
            void onLogCall(record.requestId, buildQuickCallDraft("no_interest", "Eingang"));
          }}
          className="rounded-full border border-rose-200 bg-rose-50 px-3 py-2 text-xs font-medium text-rose-800 transition hover:border-rose-300 hover:bg-rose-100 disabled:cursor-not-allowed disabled:opacity-50"
        >
          Kein Interesse
        </button>
        <button
          type="button"
          disabled={runningRequestId === record.requestId}
          onClick={(event) => {
            event.stopPropagation();
            void onLogCall(record.requestId, buildQuickCallDraft("delete_requested", "Eingang"));
          }}
          className="rounded-full border border-black/10 bg-black px-3 py-2 text-xs font-medium text-white transition hover:bg-black/85 disabled:cursor-not-allowed disabled:opacity-50"
        >
          Kontaktstopp
        </button>
      </div>
    </div>
  );
}

function WorkboardLane({
  section,
  onOpen,
  onOpenPortfolio,
  onOpenCommercialDesk,
  onHandled,
  onSnooze,
  onRescheduleFollowups,
  onScheduleCallback,
  onStartSalesRecovery,
  onApplyOutcome,
  onLogCall,
  onPauseFollowups,
  onRepairDownstreamSync,
  runningRequestId,
  simpleView = false,
}: {
  section: CustomerWorkboardSection;
  onOpen: (record: CustomerSearchResult) => void;
  onOpenPortfolio: (record: CustomerSearchResult) => void;
  onOpenCommercialDesk: (record: CustomerSearchResult) => void;
  onHandled: (requestId: string) => Promise<void>;
  onSnooze: (requestId: string, resumeAt: string) => Promise<void>;
  onRescheduleFollowups: (requestId: string, resumeAt: string, reason: string) => Promise<void>;
  onScheduleCallback: (requestId: string, resumeAt: string, reason: string) => Promise<void>;
  onStartSalesRecovery: (requestId: string, reason: string) => Promise<void>;
  onApplyOutcome: (requestId: string, outcome: CaseOutcomeDraft) => Promise<void>;
  onLogCall: (requestId: string, call: CallLogDraft) => Promise<void>;
  onPauseFollowups: (requestId: string) => Promise<void>;
  onRepairDownstreamSync: (requestId: string) => Promise<void>;
  runningRequestId: string | null;
  simpleView?: boolean;
}) {
  const tones: Record<CustomerWorkboardSection["key"], string> = {
    due_followups: "border-amber-200 bg-amber-50",
    callbacks: "border-sky-200 bg-sky-50",
    sales_recovery: "border-emerald-200 bg-emerald-50",
    recent_replies: "border-emerald-200 bg-emerald-50",
    contact_stops: "border-rose-200 bg-rose-50",
  };
  const [showAllSimpleRecords, setShowAllSimpleRecords] = useState(false);
  const visibleResults = simpleView && !showAllSimpleRecords ? section.results.slice(0, 3) : section.results;

  return (
    <div className={`rounded-2xl border p-4 ${tones[section.key]}`}>
      <div className="flex items-start justify-between gap-3">
        <div>
          <div className="text-sm font-semibold text-black">{section.title}</div>
          <div className="mt-1 text-sm leading-5 text-black/60">{simpleView ? shortSectionSubtitle(section) : section.subtitle}</div>
        </div>
        <div className="rounded-full border border-black/10 bg-white px-2.5 py-1 text-[10px] uppercase tracking-[0.14em] text-black/55">
          {section.results.length}
        </div>
      </div>
      <div className="mt-4 space-y-3">
        {visibleResults.length ? (
          visibleResults.map((record) => (
            <div
              key={`${section.key}-${record.requestId}`}
              className={`rounded-xl border border-black/10 bg-white transition hover:border-[#fa31a2]/35 hover:bg-[#fa31a2]/[0.03] ${simpleView ? "p-3" : "p-3"}`}
            >
              <button
                type="button"
                onClick={() => onOpen(record)}
                className="w-full text-left"
              >
                <div className="flex flex-wrap items-center gap-2">
                  <div className="text-sm font-semibold text-black">{record.displayName || record.request?.title || record.requestId}</div>
                  <ActiveViewerBadge record={record} />
                </div>
                <div className="mt-2 text-sm leading-6 text-black/60">
                  {simpleView
                    ? record.affectedRows.nextPendingFollowupAt
                      ? `Nächste Erinnerung ${formatDate(record.affectedRows.nextPendingFollowupAt)}`
                      : record.request?.status || "Offen"
                    : `${record.request?.status || "Stand ausstehend"}${record.affectedRows.nextPendingFollowupAt ? ` • ${formatDate(record.affectedRows.nextPendingFollowupAt)}` : ""}`}
                </div>
              </button>
              {!simpleView ? <RecommendedActionInline record={record} /> : null}
              <div className="mt-3">
                {simpleView ? <SimpleSpecialCaseFlag record={record} /> : null}
                <RecommendedPrimaryAction
                  record={record}
                  surface={simpleView ? "Nach Arbeitsblöcken" : "Arbeitsbereiche"}
                  runningRequestId={runningRequestId}
                  onRescheduleFollowups={onRescheduleFollowups}
                  onScheduleCallback={onScheduleCallback}
                  onStartSalesRecovery={onStartSalesRecovery}
                  onPauseFollowups={onPauseFollowups}
                  onRepairDownstreamSync={onRepairDownstreamSync}
                  onApplyOutcome={onApplyOutcome}
                  onOpenContactPortfolio={() => onOpenPortfolio(record)}
                  onOpenCommercialDesk={() => onOpenCommercialDesk(record)}
                  showFlowAssist
                  onOpenRecord={() => onOpen(record)}
                />
              </div>
              {!simpleView ? (
              <div className="mt-3 flex flex-wrap gap-2">
                {section.key === "recent_replies" ? (
                  <a
                    href={buildOutlookComposeUrl(
                      record.email,
                      record.displayName,
                      record.communications.find((entry) => entry.direction === "inbound")?.title
                        ? `Re: ${record.communications.find((entry) => entry.direction === "inbound")?.title}`
                        : `Re: ${record.displayName || "NEONTRIP Anfrage"}`,
                    )}
                    target="_blank"
                    rel="noreferrer"
                    className="rounded-full border border-black/10 bg-white px-3 py-2 text-xs font-medium text-black/65 transition hover:border-[#fa31a2] hover:text-black"
                  >
                    Antworten
                  </a>
                ) : null}
                {section.key === "callbacks" ? (
                  <button
                    type="button"
                    disabled={runningRequestId === record.requestId}
                    onClick={() => void onScheduleCallback(record.requestId, buildTomorrowAt(10), "Rückruf auf morgen verschoben.")}
                    className="rounded-full border border-black/10 bg-white px-3 py-2 text-xs font-medium text-black/65 transition hover:border-[#fa31a2] hover:text-black disabled:cursor-not-allowed disabled:opacity-50"
                  >
                    Rückruf morgen
                  </button>
                ) : null}
                <button
                  type="button"
                  disabled={runningRequestId === record.requestId}
                  onClick={() => void onLogCall(record.requestId, buildQuickCallDraft("voicemail", "Arbeitsbereiche"))}
                  className="rounded-full border border-black/10 bg-white px-3 py-2 text-xs font-medium text-black/65 transition hover:border-[#fa31a2] hover:text-black disabled:cursor-not-allowed disabled:opacity-50"
                >
                  Anrufbeantworter
                </button>
                <button
                  type="button"
                  disabled={runningRequestId === record.requestId}
                  onClick={() => void onLogCall(record.requestId, buildQuickCallDraft("reached", "Arbeitsbereiche"))}
                  className="rounded-full border border-black/10 bg-white px-3 py-2 text-xs font-medium text-black/65 transition hover:border-[#fa31a2] hover:text-black disabled:cursor-not-allowed disabled:opacity-50"
                >
                  Erreicht
                </button>
                <button
                  type="button"
                  disabled={runningRequestId === record.requestId}
                  onClick={() => void onLogCall(record.requestId, buildQuickCallDraft("vacation", "Arbeitsbereiche"))}
                  className="rounded-full border border-amber-200 bg-amber-50 px-3 py-2 text-xs font-medium text-amber-800 transition hover:border-amber-300 hover:bg-amber-100 disabled:cursor-not-allowed disabled:opacity-50"
                >
                  Urlaub
                </button>
                {section.key === "due_followups" ? (
                  <button
                    type="button"
                    disabled={runningRequestId === record.requestId}
                    onClick={() => void onRescheduleFollowups(record.requestId, buildTomorrowAt(10), "Erinnerung auf morgen verschoben.")}
                    className="rounded-full border border-black/10 bg-white px-3 py-2 text-xs font-medium text-black/65 transition hover:border-[#fa31a2] hover:text-black disabled:cursor-not-allowed disabled:opacity-50"
                  >
                    Erinnerung auf morgen
                  </button>
                ) : null}
                <button
                  type="button"
                  disabled={runningRequestId === record.requestId}
                  onClick={() => void onLogCall(record.requestId, buildQuickCallDraft("no_interest", "Arbeitsbereiche"))}
                  className="rounded-full border border-rose-200 bg-rose-50 px-3 py-2 text-xs font-medium text-rose-800 transition hover:border-rose-300 hover:bg-rose-100 disabled:cursor-not-allowed disabled:opacity-50"
                >
                  Kein Interesse
                </button>
                <button
                  type="button"
                  disabled={runningRequestId === record.requestId}
                  onClick={() => void onLogCall(record.requestId, buildQuickCallDraft("delete_requested", "Arbeitsbereiche"))}
                  className="rounded-full border border-black/10 bg-black px-3 py-2 text-xs font-medium text-white transition hover:bg-black/85 disabled:cursor-not-allowed disabled:opacity-50"
                >
                  Kontaktstopp
                </button>
                <button
                  type="button"
                  disabled={runningRequestId === record.requestId}
                  onClick={() => onHandled(record.requestId)}
                  className="rounded-full border border-black/10 bg-white px-3 py-2 text-xs font-medium text-black/65 transition hover:border-[#fa31a2] hover:text-black disabled:cursor-not-allowed disabled:opacity-50"
                >
                  Erledigt
                </button>
                <button
                  type="button"
                  disabled={runningRequestId === record.requestId}
                  onClick={() => {
                    const tomorrow = new Date(Date.now() + 24 * 60 * 60 * 1000);
                    tomorrow.setMinutes(0, 0, 0);
                    void onSnooze(record.requestId, tomorrow.toISOString());
                  }}
                  className="rounded-full border border-black/10 bg-white px-3 py-2 text-xs font-medium text-black/65 transition hover:border-[#fa31a2] hover:text-black disabled:cursor-not-allowed disabled:opacity-50"
                >
                  Später
                </button>
              </div>
              ) : null}
            </div>
          ))
        ) : (
          <div className="rounded-xl border border-dashed border-black/10 bg-white/60 px-3 py-3 text-sm leading-6 text-black/50">
            Aktuell keine passenden Fälle in dieser Spur.
          </div>
        )}
        {simpleView && section.results.length > 3 ? (
          <button
            type="button"
            onClick={() => setShowAllSimpleRecords((current) => !current)}
            className="rounded-full border border-black/10 bg-white px-4 py-2 text-sm font-medium text-black/60 transition hover:border-[#fa31a2] hover:text-black"
          >
            {showAllSimpleRecords
              ? "Weniger zeigen"
              : `${section.results.length - visibleResults.length} weitere zeigen`}
          </button>
        ) : null}
      </div>
    </div>
  );
}

function FocusSessionBar({
  session,
  loading,
  onPrev,
  onNext,
  onClose,
}: {
  session: FocusSession;
  loading: boolean;
  onPrev: () => void;
  onNext: () => void;
  onClose: () => void;
}) {
  const currentNumber = session.currentIndex + 1;
  const total = session.requestIds.length;
  const atStart = session.currentIndex <= 0;
  const atEnd = session.currentIndex >= total - 1;
  const sourceLabel = getSessionSourceLabel(session.source, session.badgeLabel);
  const sessionDetail = getSessionDetail(session.badgeLabel);
  const sessionLabel = getFocusSessionLabel(session.label, session.badgeLabel);

  return (
    <div className="rounded-2xl border border-[#fa31a2]/20 bg-[linear-gradient(135deg,#fff7fb_0%,#ffffff_48%,#f8fbff_100%)] p-4 shadow-[0_8px_24px_rgba(250,49,162,0.08)]">
      <div className="flex flex-col gap-4 lg:flex-row lg:items-center lg:justify-between">
        <div className="min-w-0">
          <div className="flex flex-wrap items-center gap-2">
            <span className="inline-flex items-center rounded-full border border-[#fa31a2]/20 bg-[#fa31a2]/6 px-3 py-1 text-[10px] font-medium uppercase tracking-[0.16em] text-[#c21876]">
              {sourceLabel}
            </span>
            <span className="inline-flex items-center rounded-full border border-black/10 bg-white px-3 py-1 text-[10px] font-medium uppercase tracking-[0.16em] text-black/50">
              {currentNumber} / {total}
            </span>
          </div>
          <div className="mt-2 text-sm font-semibold text-black">{sessionLabel}</div>
          <div className="mt-1 text-sm leading-6 text-black/60">
            {sessionDetail}
          </div>
        </div>
        <div className="flex flex-wrap gap-2">
          <button
            type="button"
            onClick={onPrev}
            disabled={loading || atStart}
            className="rounded-full border border-black/10 bg-white px-4 py-2 text-sm font-medium text-black/65 transition hover:border-[#fa31a2] hover:text-black disabled:cursor-not-allowed disabled:opacity-50"
          >
            Vorheriger Fall
          </button>
          <button
            type="button"
            onClick={onNext}
            disabled={loading || atEnd}
            className="rounded-full border border-black/10 bg-white px-4 py-2 text-sm font-medium text-black/65 transition hover:border-[#fa31a2] hover:text-black disabled:cursor-not-allowed disabled:opacity-50"
          >
            Nächster Fall
          </button>
          <button
            type="button"
            onClick={onClose}
            className="rounded-full border border-black/10 bg-white px-4 py-2 text-sm font-medium text-black/60 transition hover:border-[#fa31a2] hover:text-black"
          >
            Lage verlassen
          </button>
        </div>
      </div>
    </div>
  );
}

