function formatApiError(payload: { error?: string; issues?: string[] } | null) {
  if (!payload) return "Unbekannter Fehler.";
  if (payload.issues?.length) return payload.issues.join(" ");
  if (payload.error === "invalid_token") return "Zugangscode ungültig.";
  if (payload.error === "ops_not_configured") return "Zugang ist noch nicht eingerichtet.";
  return payload.error || "Unbekannter Fehler.";
}

function getInlineSearchErrorHint(error: string | null, localMode: boolean) {
  if (!error) return null;
  if (error.includes("Supabase Server-Konfiguration fehlt")) {
    return localMode
      ? "Die Oberfläche läuft, aber die lokale Suche hat noch keine Server-Anbindung zu Supabase."
      : "Die Suche ist erreichbar, aber auf dem Server fehlt noch die Supabase-Anbindung.";
  }
  if (error.includes("Zugang ist noch nicht eingerichtet")) {
    return localMode
      ? "Die Oberfläche läuft, die lokale Such-Anbindung aber noch ohne vollständige Zugriffskonfiguration."
      : "Der Zugriff ist freigeschaltet, aber die Such-Anbindung ist noch nicht vollständig eingerichtet.";
  }
  if (error.includes("Zugang abgelaufen")) {
    return localMode
      ? "Im lokalen Zugriff sollte das nicht passieren; prüfe, ob noch ein alter Browserzustand oder ein gemischter Start aktiv ist."
      : "Bitte den Zugang erneut entsperren und die Suche danach wiederholen.";
  }
  return null;
}

function formatChangedTables(changedTables: NonNullable<CustomerUpdateResponse["changedTables"]>) {
  return [
    `Führender Kontakt ${changedTables.masterCustomers}`,
    `Erinnerungsspur ${changedTables.followupQueue}`,
    `Erinnerungspläne ${changedTables.leadFollowupPlans}`,
    `Dokumente ${changedTables.documentJourney}`,
  ].join(" • ");
}

function formatDate(value: string | null | undefined) {
  if (!value) return "Kein Termin";
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) return value;
  return new Intl.DateTimeFormat("de-DE", {
    dateStyle: "medium",
    timeStyle: "short",
  }).format(date);
}

function formatActiveSeconds(value: number | null | undefined) {
  const seconds = Math.max(0, Math.round(Number(value || 0)));
  if (!seconds) return "Keine aktive Zeit";
  if (seconds < 60) return `${seconds} Sek.`;
  const minutes = Math.floor(seconds / 60);
  const restSeconds = seconds % 60;
  if (minutes < 60) return restSeconds ? `${minutes} Min ${restSeconds} Sek.` : `${minutes} Min`;
  const hours = Math.floor(minutes / 60);
  const restMinutes = minutes % 60;
  return restMinutes ? `${hours} Std ${restMinutes} Min` : `${hours} Std`;
}

function getOfferTrackingEventLabel(value: string | null | undefined) {
  switch (String(value || "").trim()) {
    case "offer_opened":
      return "Angebot geöffnet";
    case "heartbeat":
      return "Aktive Zeit";
    case "video_played":
      return "Video gestartet";
    case "video_completed":
      return "Video abgeschlossen";
    case "pdf_downloaded":
      return "PDF heruntergeladen";
    case "cta_clicked":
      return "Aktion geklickt";
    case "options_changed":
      return "Auswahl geändert";
    case "accept_started":
      return "Freigabe gestartet";
    case "accepted":
      return "Angenommen";
    case "contact_clicked":
      return "Kontakt geklickt";
    case "contact_sent":
      return "Nachricht gesendet";
    default:
      return value || "Noch kein Ereignis";
  }
}

const FLOW_STALE_AFTER_MS = 24 * 60 * 60 * 1000;
const opsViewerKey = "neontrip-ops-viewer-key";

function getOrCreateOpsViewerKey() {
  if (typeof window === "undefined") return "server";
  const existing = window.localStorage.getItem(opsViewerKey);
  if (existing) return existing;
  const next =
    typeof crypto !== "undefined" && "randomUUID" in crypto
      ? crypto.randomUUID()
      : `viewer-${Date.now()}-${Math.random().toString(16).slice(2)}`;
  window.localStorage.setItem(opsViewerKey, next);
  return next;
}

function getRelativeDurationLabel(ms: number) {
  if (ms < 2 * 60 * 60 * 1000) return "seit über 1 Stunde";
  if (ms < 24 * 60 * 60 * 1000) return `seit ${Math.max(2, Math.floor(ms / (60 * 60 * 1000)))} Stunden`;
  const days = Math.max(1, Math.floor(ms / (24 * 60 * 60 * 1000)));
  return days === 1 ? "seit 1 Tag" : `seit ${days} Tagen`;
}

function getShortRelativeSeenLabel(value: string | null | undefined) {
  if (!value) return "gerade";
  const age = Date.now() - new Date(value).getTime();
  if (!Number.isFinite(age) || age < 60 * 1000) return "gerade";
  return `seit ${Math.max(1, Math.floor(age / 60000))} Min`;
}

function ActiveViewerBadge({ record }: { record: CustomerSearchResult }) {
  const currentViewerKey = typeof window !== "undefined" ? window.localStorage.getItem(opsViewerKey) : null;
  const viewers = (record.activeViewers || []).filter((viewer) => viewer.viewerKey !== currentViewerKey);
  if (!viewers.length) return null;
  const lead = viewers[0];
  return (
    <span
      title="Dieser Hinweis ist nur ein Live-Hinweis, kein Sperrmechanismus."
      className="inline-flex rounded-full border border-sky-200 bg-sky-50 px-2.5 py-1 text-[10px] font-medium uppercase tracking-[0.14em] text-sky-800"
    >
      {lead.operatorName} {getShortRelativeSeenLabel(lead.lastSeenAt)}
    </span>
  );
}

function getActiveFlowAgeMs(record: CustomerSearchResult) {
  if (record.caseFlow.status !== "active" || !record.caseFlow.updatedAt) return null;
  const updatedAtMs = new Date(record.caseFlow.updatedAt).getTime();
  if (Number.isNaN(updatedAtMs)) return null;
  return Math.max(0, Date.now() - updatedAtMs);
}

function isActiveFlowStale(record: CustomerSearchResult) {
  if (record.caseFlow.status !== "active") return false;
  const ageMs = getActiveFlowAgeMs(record);
  if (ageMs === null) return true;
  return ageMs >= FLOW_STALE_AFTER_MS;
}

function getActiveFlowFreshnessLabel(record: CustomerSearchResult) {
  if (record.caseFlow.status !== "active") return null;
  if (!record.caseFlow.updatedAt) return "Kein Ablauf-Update protokolliert";
  const ageMs = getActiveFlowAgeMs(record);
  if (ageMs === null) return `Zuletzt ${formatDate(record.caseFlow.updatedAt)}`;
  if (isActiveFlowStale(record)) return `${getRelativeDurationLabel(ageMs)} ohne Fortschritt`;
  return `Zuletzt ${formatDate(record.caseFlow.updatedAt)}`;
}

function ActiveFlowFreshnessPill({
  record,
  className = "",
}: {
  record: CustomerSearchResult;
  className?: string;
}) {
  if (record.caseFlow.status !== "active") return null;
  const stale = isActiveFlowStale(record);
  const detail = getActiveFlowFreshnessLabel(record);

  return (
    <span
      className={`inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[10px] uppercase tracking-[0.14em] ${
        stale
          ? "border-amber-300/60 bg-amber-50 text-amber-900"
          : "border-violet-200 bg-violet-50 text-violet-900"
      } ${className}`.trim()}
    >
      <Clock3 className="h-3.5 w-3.5" />
      {stale ? "Ablauf stockt" : "Ablauf läuft"}
      {detail ? <span className="hidden opacity-70 sm:inline">{detail}</span> : null}
    </span>
  );
}

function displayChangeValue(value: string | null | undefined) {
  return value && value.trim() ? value : "Leer";
}

function formatMoney(value: number | null | undefined, currency = "EUR") {
  if (value === null || value === undefined) return "Kein Wert";
  return new Intl.NumberFormat("de-DE", {
    style: "currency",
    currency,
    maximumFractionDigits: 0,
  }).format(value);
}

function isOfferItemSelected(item: Pick<OpsOfferItem, "selectable" | "selectedByDefault">) {
  return !item.selectable || item.selectedByDefault;
}

function formatSegmentConfidence(value: number | null | undefined) {
  if (value === null || value === undefined || !Number.isFinite(value)) return null;
  const normalized = value <= 1 ? value * 100 : value;
  return `${Math.round(normalized)}% sicher`;
}

function getSegmentStatusLabel(status: string | null | undefined) {
  if (!status) return "Noch offen";
  const normalized = status.trim().toLowerCase();
  if (normalized === "accepted") return "bestätigt";
  if (normalized === "needs_review") return "prüfen";
  if (normalized === "rejected") return "verworfen";
  if (normalized === "failed") return "Fehler";
  return status;
}

function getAiSegmentLabel(request: CustomerRequestSummary | null | undefined) {
  if (!request) return "Noch keine Anfrage";
  return request.segmentLabel || getCustomerSegmentOption(request.segment)?.label || request.segment || request.sKategorie || "Noch nicht segmentiert";
}

function getAiSegmentDetail(request: CustomerRequestSummary | null | undefined) {
  if (!request) return "Kein Segmentstatus";
  const parts = [
    request.segment,
    request.sKategorie,
    getSegmentStatusLabel(request.segmentStatus),
    formatSegmentConfidence(request.segmentConfidence),
  ].filter(Boolean);
  return parts.length ? parts.join(" • ") : "Kein Segmentstatus";
}

function shouldConfirmAiSegment(request: CustomerRequestSummary | null | undefined) {
  if (!request?.segment) return true;
  const status = request.segmentStatus?.trim().toLowerCase();
  const confidence = request.segmentConfidence ?? null;
  return status !== "accepted" || confidence === null || confidence < 0.75;
}

function aiSegmentPillClass(status: string | null | undefined) {
  const normalized = status?.trim().toLowerCase();
  if (normalized === "accepted") return "border-emerald-200 bg-emerald-50 text-emerald-800";
  if (normalized === "needs_review") return "border-amber-200 bg-amber-50 text-amber-900";
  if (normalized === "failed" || normalized === "rejected") return "border-rose-200 bg-rose-50 text-rose-900";
  return "border-black/10 bg-white text-black/45";
}

function aiSegmentHeaderPillClass(status: string | null | undefined) {
  const normalized = status?.trim().toLowerCase();
  if (normalized === "accepted") return "border-emerald-300/25 bg-emerald-400/12 text-emerald-100";
  if (normalized === "needs_review") return "border-amber-300/25 bg-amber-300/12 text-amber-100";
  if (normalized === "failed" || normalized === "rejected") return "border-rose-300/25 bg-rose-400/12 text-rose-100";
  return "border-white/12 bg-white/8 text-white/68";
}

function SegmentConfirmControl({
  request,
  running,
  onApply,
}: {
  request: CustomerRequestSummary | null | undefined;
  running: boolean;
  onApply: (segment: string) => Promise<void>;
}) {
  const currentSegment = getCustomerSegmentOption(request?.segment)?.segment || "";
  const [selectedSegment, setSelectedSegment] = useState(currentSegment);
  const needsReview = shouldConfirmAiSegment(request);
  const selectedOption = getCustomerSegmentOption(selectedSegment);
  const changed = Boolean(selectedSegment && selectedSegment !== currentSegment);
  const canApply = Boolean(selectedSegment) && !running && (changed || needsReview);

  useEffect(() => {
    setSelectedSegment(currentSegment);
  }, [currentSegment]);

  return (
    <div
      className={`mt-3 rounded-xl border p-3 ${
        needsReview
          ? "border-amber-200 bg-amber-50"
          : "border-black/10 bg-white"
      }`}
    >
      <div className="flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between">
        <div className="min-w-0">
          <div className={`text-[11px] font-medium uppercase tracking-[0.18em] ${needsReview ? "text-amber-700" : "text-black/45"}`}>Segment</div>
          <div className="mt-1 text-sm font-semibold text-black">
            {getAiSegmentLabel(request)}
          </div>
          <div className={`mt-1 text-xs ${needsReview ? "text-amber-900/70" : "text-black/55"}`}>
            {needsReview ? "Bitte Segment prüfen und bestätigen." : getAiSegmentDetail(request)}
          </div>
        </div>
        <div className="flex w-full flex-col gap-2 sm:w-auto sm:flex-row sm:items-center">
          <select
            value={selectedSegment}
            onChange={(event) => setSelectedSegment(event.target.value)}
            className="h-10 min-w-[220px] rounded-lg border border-black/10 bg-white px-3 text-sm font-medium text-black outline-none transition focus:border-[#fa31a2] focus:shadow-[0_0_0_2px_rgba(250,49,162,0.12)] disabled:cursor-not-allowed disabled:bg-black/[0.03] disabled:text-black/35"
            aria-label="Segment auswählen"
            disabled={running}
          >
            <option value="">Segment wählen</option>
            {CUSTOMER_SEGMENT_OPTIONS.map((option) => (
              <option key={option.segment} value={option.segment}>
                {option.label}
              </option>
            ))}
          </select>
          <button
            type="button"
            disabled={!canApply}
            onClick={() => selectedOption ? onApply(selectedOption.segment) : undefined}
            className="h-10 min-w-[132px] whitespace-nowrap rounded-lg border border-[#0A0A0A] bg-[#0A0A0A] px-4 text-sm font-semibold text-white shadow-sm transition hover:bg-black/90 disabled:cursor-not-allowed disabled:border-black/25 disabled:bg-white disabled:text-[#111111] disabled:shadow-none"
          >
            {running ? "Speichert..." : changed ? "Segment speichern" : needsReview ? "Segment bestätigen" : "Bestätigt"}
          </button>
        </div>
      </div>
    </div>
  );
}

function orderSourceLabel(source: "master_orders" | "orders_by_email" | "crm_sales") {
  if (source === "orders_by_email") return "E-Mail-Abgleich";
  if (source === "crm_sales") return "Verkaufsdaten";
  return "Auftragsdaten";
}

function buildOutlookComposeUrl(email: string, name?: string | null, subject?: string | null, ccEmails: string[] = []) {
  const url = new URL("https://outlook.office.com/mail/deeplink/compose");
  url.searchParams.set("to", email);
  const cc = ccEmails.map((entry) => entry.trim()).filter(Boolean);
  if (cc.length) url.searchParams.set("cc", cc.join(";"));
  url.searchParams.set("subject", subject || (name ? `NEONTRIP | ${name}` : "NEONTRIP"));
  return url.toString();
}

function buildTomorrowAt(hour = 10) {
  const target = new Date(Date.now() + 24 * 60 * 60 * 1000);
  target.setHours(hour, 0, 0, 0);
  return target.toISOString();
}

function buildDaysFromNowAt(days: number, hour = 10) {
  const target = new Date(Date.now() + days * 24 * 60 * 60 * 1000);
  target.setHours(hour, 0, 0, 0);
  return target.toISOString();
}

function buildQuickCallDraft(
  kind: "reached" | "voicemail" | "no_interest" | "vacation" | "delete_requested",
  surface: string,
): CallLogDraft {
  return {
    reached: kind === "reached",
    leftVoicemail: kind === "voicemail",
    customerOnVacation: kind === "vacation",
    askedForCallback: false,
    noInterest: kind === "no_interest",
    emailConfirmed: false,
    offerDiscussed: false,
    whatsappPreferred: false,
    deleteRequested: kind === "delete_requested",
    note:
      kind === "reached"
        ? `Direkt aus ${surface} als erreicht protokolliert.`
        : kind === "voicemail"
          ? `Direkt aus ${surface} als Anrufbeantworter protokolliert.`
          : kind === "vacation"
            ? `Direkt aus ${surface} als Urlaub protokolliert.`
            : kind === "delete_requested"
              ? `Direkt aus ${surface} als Lösch-/Kontaktstopp protokolliert.`
              : `Direkt aus ${surface} als kein Interesse protokolliert.`,
  };
}

