function buildPlacetelLink(template: string | null, record: CustomerSearchResult) {
  if (!template) return null;
  const query = record.phone || record.email || record.displayName || record.requestId;
  if (!query) return null;
  return template
    .replaceAll("{phone}", encodeURIComponent(record.phone || ""))
    .replaceAll("{email}", encodeURIComponent(record.email || ""))
    .replaceAll("{query}", encodeURIComponent(query));
}

function buildPreviewSignature(updates: CustomerUpdateFields) {
  const ccEmails = Array.isArray(updates.ccEmails) ? updates.ccEmails : [];
  return JSON.stringify({
    email: updates.email || "",
    billingEmail: updates.billingEmail || "",
    ccEmails: ccEmails.map((entry) => entry.trim()).filter(Boolean),
    firstName: updates.firstName || "",
    lastName: updates.lastName || "",
    phone: updates.phone || "",
    company: updates.company || "",
  });
}

