  function resolveSessionMaps(
    currentRequestId: string,
    session: SessionOpenPayload,
  ) {
    const preferredTabsByRequestId =
      session.preferredTabsByRequestId ||
      Object.fromEntries(
        session.requestIds.map((requestId) => {
          const visibleRecord = visibleSessionRecordMap.get(requestId);
          if (visibleRecord) {
            const sessionMeta = resolveRecordSessionMeta(visibleRecord);
            if (requestId === currentRequestId && session.preferredTab) {
              return [requestId, session.preferredTab];
            }
            return [requestId, sessionMeta.preferredTab ?? inferPreferredTab(visibleRecord)];
          }
          return [requestId, session.preferredTab ?? null];
        }),
      );
    const badgeLabelsByRequestId =
      session.badgeLabelsByRequestId ||
      Object.fromEntries(
        session.requestIds.map((requestId) => {
          const visibleRecord = visibleSessionRecordMap.get(requestId);
          if (visibleRecord) {
            if (requestId === currentRequestId && session.badgeLabel) {
              return [requestId, session.badgeLabel];
            }
            return [requestId, resolveRecordSessionMeta(visibleRecord).badgeLabel];
          }
          return [requestId, session.badgeLabel];
        }),
      );

    return {
      preferredTabsByRequestId,
      badgeLabelsByRequestId,
    };
  }

  function openQueueRecord(
    record: CustomerSearchResult,
    session: SessionOpenPayload,
  ) {
    const { preferredTabsByRequestId, badgeLabelsByRequestId } = resolveSessionMaps(record.requestId, session);
    const preferredTab = preferredTabsByRequestId[record.requestId] ?? session.preferredTab ?? inferPreferredTab(record);
    const index = session.requestIds.indexOf(record.requestId);
    setFocusSession({
      source: session.source,
      badgeLabel: badgeLabelsByRequestId[record.requestId] ?? session.badgeLabel,
      label: session.label,
      requestIds: session.requestIds,
      currentIndex: index >= 0 ? index : 0,
      preferredTab,
      preferredTabsByRequestId,
      badgeLabelsByRequestId,
    });
    rememberRecentCase(record);
    void loadRecordByRequestId(record.requestId, preferredTab);
  }

  function openRequestIdInSession(
    requestId: string,
    session: SessionOpenPayload,
  ) {
    const { preferredTabsByRequestId, badgeLabelsByRequestId } = resolveSessionMaps(requestId, session);
    const preferredTab = preferredTabsByRequestId[requestId] ?? session.preferredTab ?? null;
    const index = session.requestIds.indexOf(requestId);
    setFocusSession({
      source: session.source,
      badgeLabel: badgeLabelsByRequestId[requestId] ?? session.badgeLabel,
      label: session.label,
      requestIds: session.requestIds,
      currentIndex: index >= 0 ? index : 0,
      preferredTab,
      preferredTabsByRequestId,
      badgeLabelsByRequestId,
    });
    const cachedRecord = visibleSessionRecordMap.get(requestId);
    if (cachedRecord) {
      rememberRecentCase(cachedRecord);
    }
    void loadRecordByRequestId(requestId, preferredTab);
  }

  function getFocusSessionPreferredTab(session: FocusSession, requestId: string) {
    return session.preferredTabsByRequestId?.[requestId] ?? session.preferredTab;
  }

  function getFocusSessionBadgeLabel(session: FocusSession, requestId: string) {
    return session.badgeLabelsByRequestId?.[requestId] ?? session.badgeLabel;
  }

  function navigateFocusSession(direction: -1 | 1) {
    if (!focusSession) return;
    const nextIndex = focusSession.currentIndex + direction;
    if (nextIndex < 0 || nextIndex >= focusSession.requestIds.length) return;
    const nextRequestId = focusSession.requestIds[nextIndex];
    const nextPreferredTab = getFocusSessionPreferredTab(focusSession, nextRequestId);
    const nextBadgeLabel = getFocusSessionBadgeLabel(focusSession, nextRequestId);
    setFocusSession({
      ...focusSession,
      currentIndex: nextIndex,
      badgeLabel: nextBadgeLabel,
      preferredTab: nextPreferredTab,
    });
    void loadRecordByRequestId(nextRequestId, nextPreferredTab);
  }

  function advanceFocusSessionAfterAction(requestId: string) {
    if (!focusSession) return;
    if (focusSession.requestIds[focusSession.currentIndex] !== requestId) return;

    const hasNext = focusSession.currentIndex < focusSession.requestIds.length - 1;
    const hasPrev = focusSession.currentIndex > 0;

    if (hasNext) {
      const nextIndex = focusSession.currentIndex + 1;
      const nextRequestId = focusSession.requestIds[nextIndex];
      const nextPreferredTab = getFocusSessionPreferredTab(focusSession, nextRequestId);
      const nextBadgeLabel = getFocusSessionBadgeLabel(focusSession, nextRequestId);
      setFocusSession({
        ...focusSession,
        currentIndex: nextIndex,
        badgeLabel: nextBadgeLabel,
        preferredTab: nextPreferredTab,
      });
      void loadRecordByRequestId(nextRequestId, nextPreferredTab);
      return;
    }

    if (hasPrev) {
      const prevIndex = focusSession.currentIndex - 1;
      const prevRequestId = focusSession.requestIds[prevIndex];
      const prevPreferredTab = getFocusSessionPreferredTab(focusSession, prevRequestId);
      const prevBadgeLabel = getFocusSessionBadgeLabel(focusSession, prevRequestId);
      setFocusSession({
        ...focusSession,
        currentIndex: prevIndex,
        badgeLabel: prevBadgeLabel,
        preferredTab: prevPreferredTab,
      });
      void loadRecordByRequestId(prevRequestId, prevPreferredTab);
      return;
    }

    setFocusSession(null);
  }

  async function preview(requestId: string, updates: CustomerUpdateFields) {
    const response = await fetch("/api/ops/customer-records", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ requestId, updates }),
    });

    const payload = (await response.json().catch(() => null)) as CustomerPreviewResponse | null;
    if (response.status === 401) {
      setHasSession(false);
      throw new Error("Zugang abgelaufen. Bitte erneut entsperren.");
    }

    if (!response.ok || !payload?.ok || !payload.preview) {
      throw new Error(formatApiError(payload));
    }

    return payload.preview;
  }

  async function save(requestId: string, updates: CustomerUpdateFields) {
    setSavingRequestId(requestId);
    setError(null);
    setMessage(null);
    setLastSavedRequestId(null);
    setLastSavedSummary(null);
    setLastAdvanceableActionRequestId(null);

    try {
      const response = await fetch("/api/ops/customer-records", {
        method: "PATCH",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ requestId, updates }),
      });

      const payload = (await response.json().catch(() => null)) as CustomerUpdateResponse | null;

      if (response.status === 401) {
        const authError = "Zugang abgelaufen. Bitte erneut entsperren.";
        setHasSession(false);
        setError(authError);
        throw new Error(authError);
      }

      if (!response.ok || !payload?.ok || !payload.record || !payload.changedTables) {
        throw new Error(formatApiError(payload));
      }

      applyRecordUpdate(payload.record);
      const saveSummary = formatChangedTables(payload.changedTables);
      setMessage(`Änderungen gespeichert. Aktualisiert: ${saveSummary}.`);
      setLastSavedRequestId(requestId);
      setLastSavedSummary(saveSummary);
    } catch (error) {
      const errorMessage = error instanceof Error ? error.message : "Speichern fehlgeschlagen.";
      setError(errorMessage);
      throw new Error(errorMessage);
    } finally {
      setSavingRequestId(null);
    }
  }

  async function addNote(requestId: string, note: CustomerOpsNoteDraft) {
    setNoteSavingRequestId(requestId);
    setError(null);
    setMessage(null);

    const response = await fetch("/api/ops/customer-records/notes", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        requestId,
        note: note.note,
        kind: note.kind,
        assigneeLabel: note.assigneeLabel,
      }),
    });

    const payload = (await response.json().catch(() => null)) as NoteResponse | null;

    if (response.status === 401) {
      setHasSession(false);
      setError("Zugang abgelaufen. Bitte erneut entsperren.");
      setNoteSavingRequestId(null);
      return;
    }

    if (!response.ok || !payload?.ok || !payload.note) {
      setError(formatApiError(payload));
      setNoteSavingRequestId(null);
      return;
    }

    setResults((current) =>
      current.map((entry) =>
        entry.requestId === requestId ? { ...entry, notes: [payload.note!, ...entry.notes] } : entry,
      ),
    );
    setInbox((current) =>
      current.map((entry) =>
        entry.requestId === requestId ? { ...entry, notes: [payload.note!, ...entry.notes] } : entry,
      ),
    );
    setWorkboard((current) =>
      current.map((section) => ({
        ...section,
        results: section.results.map((entry) =>
          entry.requestId === requestId ? { ...entry, notes: [payload.note!, ...entry.notes] } : entry,
        ),
      })),
    );
    setMessage(note.kind === "task" ? "Teamaufgabe gespeichert." : note.kind === "update" ? "Team-Update gespeichert." : "Teamnotiz gespeichert.");
    setNoteSavingRequestId(null);
  }

