  async function runActionQueueBatch(draft: ActionQueueBatchDraft) {
    const { item, eligibleRecords: targets } = draft;
    if (!targets.length) return;

    if (!(item.key === "callback" || item.key === "followup" || item.key === "signal")) {
      return;
    }

    setBatchActionKey(item.key);
    setError(null);
    setMessage(null);

    try {
      for (const record of targets) {
        if (item.key === "callback") {
          await scheduleCallback(record.requestId, buildTomorrowAt(10), "Sammelaktion aus der Aktionsspur auf morgen verschoben.");
          continue;
        }

        if (item.key === "followup") {
          await runRecordAction(record.requestId, "reschedule_pending_followups", {
            resumeAt: buildTomorrowAt(10),
            reason: "Sammelaktion aus der Aktionsspur auf morgen verschoben.",
          });
          continue;
        }

        await startSalesRecovery(record.requestId, "Sammelaktion aus der Aktionsspur in die Rückgewinnung überführt.");
      }

      setMessage(
        item.key === "callback"
          ? `${targets.length} Rückruf-Fall${targets.length === 1 ? "" : "e"} auf morgen verschoben.`
          : item.key === "followup"
            ? `${targets.length} Erinnerungs-Fall${targets.length === 1 ? "" : "e"} auf morgen verschoben.`
            : `${targets.length} Rückgewinnungs-Fall${targets.length === 1 ? "" : "e"} aktiviert.`,
      );
    } catch {
      setError("Sammelaktion konnte nicht vollständig ausgeführt werden.");
    } finally {
      setBatchActionKey(null);
      setBatchDraft(null);
    }
  }

  function prepareActionQueueBatch(item: ActionQueueItem) {
    const previewRecords = item.records.slice(0, 5);
    if (!previewRecords.length) return;
    const eligibleRecords = previewRecords.filter(isBatchEligible);
    const skippedRecords = previewRecords.filter((record) => !isBatchEligible(record));
    setBatchDraft({
      item,
      records: previewRecords,
      eligibleRecords,
      skippedRecords,
    });
  }

  async function runSystemGapBatch(draft: SystemGapBatchDraft) {
    const { item, records } = draft;
    if (!records.length || !isSystemGapBatchable(item)) return;

    setSystemGapBatchKey(item.key);
    setError(null);
    setMessage(null);

    try {
      for (const record of records) {
        if (item.key === "email_drift") {
          await repairDownstreamSync(record.requestId);
          continue;
        }
        if (item.key === "blocked_followups") {
          await runRecordAction(record.requestId, "pause_pending_followups");
          continue;
        }
        if (item.key === "order_open_ops") {
          await applyCaseOutcome(record.requestId, {
            outcome: "won",
            resumeAt: "",
            reason: "Sammelaktion aus den Reparaturen als gewonnen abgeschlossen.",
          });
          continue;
        }

        await startSalesRecovery(record.requestId, "Sammelaktion aus den Reparaturen in die Rückgewinnung überführt.");
      }

      setMessage(
        item.key === "email_drift"
          ? `${records.length} Abgleichs-Fall${records.length === 1 ? "" : "e"} repariert.`
          : item.key === "blocked_followups"
            ? `${records.length} Fall${records.length === 1 ? "" : "e"} mit Kontaktstopp bereinigt.`
            : item.key === "order_open_ops"
              ? `${records.length} Auftrags-Fall${records.length === 1 ? "" : "e"} als gewonnen abgeschlossen.`
            : `${records.length} Rückgewinnungs-Fall${records.length === 1 ? "" : "e"} aktiviert.`,
      );
    } catch {
      setError("Sammelaktion für Systemfehler konnte nicht vollständig ausgeführt werden.");
    } finally {
      setSystemGapBatchKey(null);
      setSystemGapBatchDraft(null);
    }
  }

  function prepareSystemGapBatch(item: SystemGapQueueItem) {
    if (!isSystemGapBatchable(item)) return;
    const previewRecords = item.records.slice(0, 5);
    if (!previewRecords.length) return;
    setSystemGapBatchDraft({
      item,
      records:
        item.key === "viewed_without_order"
          ? previewRecords.filter((record) => Boolean(record.phone?.trim()))
          : previewRecords,
    });
  }

