  function openRecentCase(requestId: string, options?: RequestIdSessionOpenOptions) {
    setPaletteOpen(false);
    if (options?.requestIds?.length) {
      const preferredTabsByRequestId = options.preferredTabsByRequestId
        ? Object.fromEntries(
            options.requestIds.map((currentRequestId) => {
              const visibleRecord = visibleSessionRecordMap.get(currentRequestId);
              return [
                currentRequestId,
                options.preferredTabsByRequestId?.[currentRequestId] ??
                  (visibleRecord ? resolveRecordSessionMeta(visibleRecord).preferredTab ?? inferPreferredTab(visibleRecord) : null),
              ];
            }),
          )
        : undefined;
      const badgeLabelsByRequestId = options.badgeLabelsByRequestId
        ? Object.fromEntries(
            options.requestIds.map((currentRequestId) => {
              const visibleRecord = visibleSessionRecordMap.get(currentRequestId);
              return [
                currentRequestId,
                options.badgeLabelsByRequestId?.[currentRequestId] ??
                  (visibleRecord ? resolveRecordSessionMeta(visibleRecord).badgeLabel : undefined),
              ];
            }),
          )
        : undefined;
      openRequestIdInSession(requestId, {
        source: options.source || "workboard",
        badgeLabel: options.badgeLabel ?? badgeLabelsByRequestId?.[requestId],
        label: options.label || "Fallkontext",
        requestIds: options.requestIds,
        preferredTab: options.preferredTab ?? preferredTabsByRequestId?.[requestId] ?? null,
        preferredTabsByRequestId,
        badgeLabelsByRequestId,
      });
      return;
    }
    setFocusSession(null);
    setRecordPreferredTab(null);
    void loadRecordByRequestId(requestId, options?.preferredTab || null);
  }

  function openRequestIdWithOptions(
    requestId: string,
    options?: RequestIdSessionOpenOptions,
    fallbackLabel = "Weitere Fälle im Kontaktdossier",
  ) {
    if (options?.requestIds?.length) {
      openRequestIdInSession(requestId, {
        source: options.source || "workboard",
        badgeLabel: options.badgeLabel,
        label: options.label || fallbackLabel,
        requestIds: options.requestIds,
        preferredTab: options.preferredTab ?? null,
        preferredTabsByRequestId: options.preferredTabsByRequestId,
        badgeLabelsByRequestId: options.badgeLabelsByRequestId,
      });
      return;
    }
    void loadRecordByRequestId(requestId, options?.preferredTab || null);
  }

