  const commercialBriefMeta = getCommercialBriefPresentation(commercialDeskItems[0]?.records[0] || null, "global");
  const hasTeamRecords = teamRecords.length > 0;
  const hasRepairWork = repairQueueItems.length > 0;
  const hasSpecialCaseWork = specialCaseQueueItems.length > 0;
  const hasContactClusterWork = contactClusterQueueItems.length > 0;
  const hasHandovers = teamRecords.some((record) => record.caseCoordination.mode === "handover");
  const hasSystemGapWork = systemGapQueue.length > 0;
  const hasRadarSignals = radarItems.some((item) => item.count > 0);
  const hasActionQueueWork = actionQueueItems.some((item) => item.records.length > 0);
  const hasActiveFlowWork = activeFlowQueueItems.some((item) => item.records.length > 0);
  const hasCommercialDeskWork = commercialDeskItems.some((item) => item.records.length > 0);
  const hasCommercialControlWork = teamRecords.some((record) => hasCommercialDeskNonRecoveryOpportunity(record));
